window.__OPENSTAX_PHYSICS__[18] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.833Z","number":18,"code":"ch18","slug":"static-electricity","title":"Static Electricity","titleVi":"Tĩnh Điện, Điện Trường & Tụ Điện (Static Electricity)","sections":[{"uid":"hsphys.ch18.sec00","moduleId":"m54417","number":"18.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch18.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["You may have been introduced to static electricity like the child sliding down the slide in the opening photograph ([Figure 18.0]). The zap that he is likely to receive if he touches a playmate or parent tends to bring home the lesson. But static electricity is more than just fun and games—it is put to use in many industries. The forces between electrically charged particles are used in technologies such as printers, pollution filters, and spray guns used for painting cars and trucks. Static electricity is the study of phenomena that involve an imbalance of electrical charge. Although creating this imbalance typically requires moving charge around, once the imbalance is created, it often remains static for a long time. The study of charge in motion is called electromagnetism and will be covered in a later chapter. What is electrical charge, how is it associated with objects, and what forces does it create? These are just some of the questions that this chapter addresses."],"figures":[{"sourceId":"fs-id1167062537526","filename":"CNX_HSPhysics_18_00_Plasticsil.jpg","relativePath":"media/CNX_HSPhysics_18_00_Plasticsil.jpg","alt":"A photo shows a child sliding down a spiral-shaped slide, with his straight hair standing on end."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch18.sec01","moduleId":"m54410","number":"18.1","slug":"electrical-charges-conservation-of-charge-and-transfer-of-charge","title":"Electrical Charges, Conservation of Charge, and Transfer of Charge","isIntroduction":false,"learningObjectives":["Describe positive and negative electric charges","Use conservation of charge to calculate quantities of charge transferred between objects","Characterize materials as conductors or insulators based on their electrical properties","Describe electric polarization and charging by induction"],"bilingualGuide":{"notebookSummaryVi":"Điện tích nguyên tố, Bảo toàn điện tích, Chất dẫn điện vs Cách điện và 3 cách nhiễm điện (cọ xát, tiếp xúc, hưởng ứng).","wordProblemCues":[{"phraseEn":"elementary charge e","meaningVi":"Điện tích nguyên tố 1.60 × 10⁻¹⁹ C","mathNotation":"e = 1.60×10⁻¹⁹ C"}],"commonTrapsVi":["Vật nhiễm điện DƯƠNG là do thiếu electron (mất e⁻), KHÔNG bao giờ do nhận thêm proton!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch18.sec01.sub01","title":"Electric Charge","summaryVi":null,"paragraphs":["You may know someone who has an electric personality, which usually means that other people are attracted to this person. This saying is based on electric charge, which is a property of matter that causes objects to attract or repel each other. Electric charge comes in two varieties, which we call positive and negative. Like charges repel each other, and unlike charges attract each other. Thus, two positive charges repel each other, as do two negative charges . A positive charge and a negative charge attract each other.","How do we know there are two types of electric charge? When various materials are rubbed together in controlled ways, certain combinations of materials always result in a net charge of one type on one material and a net charge of the opposite type on the other material. By convention, we call one type of charge positive and the other type negative. For example, when glass is rubbed with silk, the glass becomes positively charged and the silk negatively charged. Because the glass and silk have opposite charges, they attract one another like clothes that have rubbed together in a dryer. Two glass rods rubbed with silk in this manner will repel one another, because each rod has positive charge on it. Similarly, two silk cloths rubbed in this manner will repel each other, because both cloths have negative charge. [Figure 18.1] shows how these simple materials can be used to explore the nature of the force between charges.","It took scientists a long time to discover what lay behind these two types of charges. The word electric itself comes from the Greek word elektron for amber, because the ancient Greeks noticed that amber, when rubbed by fur, attracts dry straw. Almost 2,000 years later, the English physicist William Gilbert proposed a model that explained the effect of electric charge as being due to a mysterious electrical fluid that would pass from one object to another. This model was debated for several hundred years, but it was finally put to rest in 1897 by the work of the English physicist J. J. Thomson and French physicist Jean Perrin. Along with many others, Thomson and Perrin were studying the mysterious cathode rays that were known at the time to consist of particles smaller than the smallest atom. Perrin showed that cathode rays actually carried negative electrical charge. Later, Thomson’s work led him to declare, “I can see no escape from the conclusion that [cathode rays] are charges of negative electricity carried by particles of matter.”","It took several years of further experiments to confirm Thomson’s interpretation of the experiments, but science had in fact discovered the particle that carries the fundamental unit of negative electrical charge. We now know this particle as the electron .","Atoms, however, were known to be electrically neutral, which means that they carry the same amount of positive and negative charge, so their net charge is zero. Because electrons are negative, some other part of the atom must contain positive charge. Thomson put forth what is called the plum pudding model , in which he described atoms as being made of thousands of electrons swimming around in a nebulous mass of positive charge, as shown by the left-side image of [Figure 18.1]. His student, Ernest Rutherford , originally believed that this model was correct and used it (along with other models) to try to understand the results of his experiments bombarding gold foils with alpha particles (i.e., helium atoms stripped of their electrons). The results, however, did not confirm Thomson’s model but rather destroyed it! Rutherford found that most of the space occupied by the gold atoms was actually empty and that almost all of the matter of each atom was concentrated into a tiny, extremely dense nucleus, as shown by the right-side image of [Figure 18.1]. The atomic nucleus was later found to contain particles called protons , each of which carries a unit of positive electric charge. Protons were later found to contain sub particles called quarks , which have fractional electric charge. But that is another story that we leave for subsequent physics courses.","Protons and electrons are thus the fundamental particles that carry electric charge. Each proton carries one unit of positive charge, and each electron carries one unit of negative charge. To the best precision that modern technology can provide, the charge carried by a proton is exactly the opposite of that carried by an electron. The SI unit for electric charge is the coulomb (abbreviated as “C”), which is named after the French physicist Charles Augustin de Coulomb, who studied the force between charged objects. The proton carries \\(+ 1.602\\, \\times \\,{10}^{-19}\\text{C.}\\) and the electron carries \\(-1.602\\, \\times \\,{10}^{-19}\\text{C,}\\) . The number n of protons required to make +1.00 C is","The same number of electrons is required to make -1.00 C of electric charge. The fundamental unit of charge is often represented as e . Thus, the charge on a proton is e , and the charge on an electron is - e . Mathematically, \\(e = + 1.602\\, \\times \\,{10}^{-19}\\text{C}\\text{.}\\)"],"figures":[{"sourceId":"fs-id1167061226663","filename":"CNX_HSPhysics_18_01_Posnegchar.jpg","relativePath":"media/CNX_HSPhysics_18_01_Posnegchar.jpg","alt":"This figure has three parts. Part a: It shows a glass rod suspended from its middle by a string and a nearby silk cloth held from its upper edge by a hand. The glass rod has a series of plus signs, and the silk cloth has many minus signs. There are several faded images of the glass rod and a downward pointing arrow, suggesting the rod's movement toward the cloth. The lower edge of the cloth bends toward the rod. Part b: It shows two glass rods near each other, each with a series of plus signs. One rod is held from one end by a hand, and the other rod is suspended from its middle by a string. There are several faded images of the suspended rod and an upward pointing arrow, suggesting its movement away from the handheld rod. Part c: It shows two silk cloths held by hand near each other, each with a number of minus signs. The lower edges of the cloths curve away from each other."},{"sourceId":"fs-id1167067294467","filename":"CNX_HSPhysics_18_01_pp.jpg","relativePath":"media/CNX_HSPhysics_18_01_pp.jpg","alt":"This figure has two drawings, side by side. The drawing on the left shows a large blue sphere, one-eighth of which has been cut out. A number of small red spheres are on the surface of the blue sphere and within the cut-away part of the blue sphere. Also, a number of faded red spheres lie within the blue sphere. The drawing on the right shows four ellipses evenly spaced around a common center, with a small blue sphere in each ellipse. Near the top is the word “Electrons,” with two lines connecting that word to two of the blue spheres. The common center contains a clump of four small red spheres and five small gray spheres. Near the top is another word, “Nucleus,” with a line connecting that word to the clump of spheres at the center."}],"tables":[]},{"uid":"hsphys.ch18.sec01.sub02","title":"Conservation of Charge","summaryVi":null,"paragraphs":["Because the fundamental positive and negative units of charge are carried on protons and electrons, we would expect that the total charge cannot change in any system that we define. In other words, although we might be able to move charge around, we cannot create or destroy it. This should be true provided that we do not create or destroy protons or electrons in our system. In the twentieth century, however, scientists learned how to create and destroy electrons and protons, but they found that charge is still conserved. Many experiments and solid theoretical arguments have elevated this idea to the status of a law. The law of conservation of charge says that electrical charge cannot be created or destroyed.","The law of conservation of charge is very useful. It tells us that the net charge in a system is the same before and after any interaction within the system. Of course, we must ensure that no external charge enters the system during the interaction and that no internal charge leaves the system. Mathematically, conservation of charge can be expressed as","where \\({q}_{\\text{initial}}\\) is the net charge of the system before the interaction, and \\({q}_{\\text{final,}}\\) is the net charge after the interaction."],"figures":[],"tables":[]},{"uid":"hsphys.ch18.sec01.sub03","title":"Conductors and Insulators","summaryVi":null,"paragraphs":["Materials can be classified depending on whether they allow charge to move. If charge can easily move through a material, such as metals, then these materials are called conductors . This means that charge can be conducted (i.e., move) through the material rather easily. If charge cannot move through a material, such as rubber, then this material is called an insulator .","Most materials are insulators. Their atoms and molecules hold on more tightly to their electrons, so it is difficult for electrons to move between atoms. However, it is not impossible. With enough energy, it is possible to force electrons to move through an insulator. However, the insulator is often physically destroyed in the process. In metals, the outer electrons are loosely bound to their atoms, so not much energy is required to make electrons move through metal. Such metals as copper, silver, and aluminum are good conductors. Insulating materials include plastics, glass, ceramics, and wood.","The conductivity of some materials is intermediate between conductors and insulators. These are called semiconductors . They can be made conductive under the right conditions, which can involve temperature, the purity of the material, and the force applied to push electrons through them. Because we can control whether semiconductors are conductors or insulators, these materials are used extensively in computer chips. The most commonly used semiconductor is silicon. [Figure 18.1] shows various materials arranged according to their ability to conduct electrons.","What happens if an excess negative charge is placed on a conducting object? Because like charges repel each other, they will push against each other until they are as far apart as they can get. Because the charge can move in a conductor, it moves to the outer surfaces of the object. [Figure 18.1](a) shows schematically how an excess negative charge spreads itself evenly over the outer surface of a metal sphere.","What happens if the same is done with an insulating object? The electrons still repel each other, but they are not able to move, because the material is an insulator. Thus, the excess charge stays put and does not distribute itself over the object. [Figure 18.1](b) shows this situation."],"figures":[{"sourceId":"fs-id1167067254090","filename":"CNX_HSPhysics_18_01_classifica.jpg","relativePath":"media/CNX_HSPhysics_18_01_classifica.jpg","alt":"Thirteen materials are arranged in a horizontal series, according to their ability to conduct electric charge. The materials, ranging from the least conductive on the left to the most conductive on the right, are: “Dry air”, “Dry wood”, “Rubber8, “Glass”, “Silicon”, “Germanium”, “Sea water”, “Carbon”, “Mercury”, “Iron”, “Aluminum”, “Copper”, and “Silver”. Above the names of the materials is a long, horizontal arrow pointing rightward. The arrow is broken in two places, producing three segments. The left segment, labeled “Insulators”, is above the materials Dry air to Glass; the middle segment, labeled “Semiconductors”, is above Silicon and Germanium; and the right segment, labeled “Conductors”, is above the materials Sea water to Silver. Below the names of the materials are numbers that give the resistivity of each material in ohm-meter."},{"sourceId":"fs-id1167067153399","filename":"CNX_HSPhysics_18_01_Conducting.jpg","relativePath":"media/CNX_HSPhysics_18_01_Conducting.jpg","alt":"This figure has two parts, each consisting of a sphere. In Part a, there are minus signs distributed relatively evenly around the sphere. In Part b, there are minus signs concentrated in the upper right quadrant of the face of the sphere."}],"tables":[]},{"uid":"hsphys.ch18.sec01.sub04","title":"Transfer and Separation of Charge","summaryVi":null,"paragraphs":["Most objects we deal with are electrically neutral, which means that they have the same amount of positive and negative charge. However, transferring negative charge from one object to another is fairly easy to do. When negative charge is transferred from one object to another, an excess of positive charge is left behind. How do we know that the negative charge is the mobile charge? The positive charge is carried by the proton, which is stuck firmly in the nucleus of atoms, and the atoms are stuck in place in solid materials. Electrons, which carry the negative charge, are much easier to remove from their atoms or molecules and can therefore be transferred more easily.","Electric charge can be transferred in several manners. One of the simplest ways to transfer charge is charging by contact, in which the surfaces of two objects made of different materials are placed in close contact. If one of the materials holds electrons more tightly than the other, then it takes some electrons with it when the materials are separated. Rubbing two surfaces together increases the transfer of electrons, because it creates a closer contact between the materials. It also serves to present fresh material with a full supply of electrons to the other material. Thus, when you walk across a carpet on a dry day, your shoes rub against the carpet, and some electrons are removed from the carpet by your shoes. The result is that you have an excess of negative charge on your shoes. When you then touch a doorknob, some of your excess of electrons transfer to the neutral doorknob, creating a small spark.","Touching the doorknob with your hand demonstrates a second way to transfer electric charge, which is charging by conduction . This transfer happens because like charges repel, and so the excess electrons that you picked up from the carpet want to be as far away from each other as possible. Some of them move to the doorknob, where they will distribute themselves over the outer surface of the metal. Another example of charging by conduction is shown in the top row of [Figure 18.1]. A metal sphere with 100 excess electrons touches a metal sphere with 50 excess electrons, so 25 electrons from the first sphere transfer to the second sphere. Each sphere finishes with 75 excess electrons.","The same reasoning applies to the transfer of positive charge. However, because positive charge essentially cannot move in solids, it is transferred by moving negative charge in the opposite direction. For example, consider the bottom row of [Figure 18.1]. The first metal sphere has 100 excess protons and touches a metal sphere with 50 excess protons, so the second sphere transfers 25 electrons to the first sphere. These 25 extra electrons will electrically cancel 25 protons so that the first metal sphere is left with 75 excess protons. This is shown in the bottom row of [Figure 18.1]. The second metal sphere lost 25 electrons so it has 25 more excess protons, for a total of 75 excess protons. The end result is the same if we consider that the first ball transferred a net positive charge equal to that of 25 protons to the first ball.","In this discussion, you may wonder how the excess electrons originally got from your shoes to your hand to create the spark when you touched the doorknob. The answer is that no electrons actually traveled from your shoes to your hands. Instead, because like charges repel each other, the excess electrons on your shoe simply pushed away some of the electrons in your feet. The electrons thus dislodged from your feet moved up into your leg and in turn pushed away some electrons in your leg. This process continued through your whole body until a distribution of excess electrons covered the extremities of your body. Thus your head, your hands, the tip of your nose, and so forth all received their doses of excess electrons that had been pushed out of their normal positions. All this was the result of electrons being pushed out of your feet by the excess electrons on your shoes.","This type of charge separation is called polarization . As soon as the excess electrons leave your shoes (by rubbing off onto the floor or being carried away in humid air), the distribution of electrons in your body returns to normal. Every part of your body is again electrically neutral (i.e., zero excess charge).","The phenomenon of polarization is seen in [Figure 18.0]. The child has accumulated excess positive charge by sliding on the slide. This excess charge repels itself and so becomes distributed over the extremities of the child’s body, notably in his hair. As a result, the hair stands on end, because the excess negative charge on each strand repels the excess negative charge on neighboring strands.","Polarization can be used to charge objects. Consider the two metallic spheres shown in [Figure 18.1]. The spheres are electrically neutral, so they carry the same amounts of positive and negative charge. In the top picture ([Figure 18.1](a)), the two spheres are touching, and the positive and negative charge is evenly distributed over the two spheres. We then approach a glass rod that carries an excess positive charge, which can be done by rubbing the glass rod with silk, as shown in [Figure 18.1](b). Because opposite charges attract each other, the negative charge is attracted to the glass rod, leaving an excess positive charge on the opposite side of the right sphere. This is an example of charging by induction , whereby a charge is created by approaching a charged object with a second object to create an unbalanced charge in the second object. If we then separate the two spheres, as shown in [Figure 18.1](c), the excess charge is stuck on each sphere. The left sphere now has an excess negative charge, and the right sphere has an excess positive charge. Finally, in the bottom picture, the rod is removed, and the opposite charges attract each other, so they move as close together as they can get.","Van de Graaff generators are devices that are used not only for serious physics research but also for demonstrating the physics of static electricity at science fairs and in classrooms. Because they deliver relatively little electric current, they can be made safe for use in such environments. The first such generator was built by Robert Van de Graaff in 1931 for use in nuclear physics research. [Figure 18.1] shows a simplified sketch of a Van de Graaff generator.","Van de Graaff generators use smooth and pointed surfaces and conductors and insulators to generate large static charges. In the version shown in [Figure 18.1], electrons are “sprayed” from the tips of the lower comb onto a moving belt, which is made of an insulating material like, such as rubber. This technique of charging the belt is akin to charging your shoes with electrons by walking across a carpet. The belt raises the charges up to the upper comb, where they transfer again, akin to your touching the doorknob and transferring your charge to it. Because like charges repel, the excess electrons all rush to the outer surface of the globe, which is made of metal (a conductor). Thus, the comb itself never accumulates too much charge, because any charge it gains is quickly depleted by the charge moving to the outer surface of the globe.","Van de Graaff generators are used to demonstrate many interesting effects caused by static electricity. By touching the globe, a person gains excess charge, so his or her hair stands on end, as shown in [Figure 18.1]. You can also create mini lightning bolts by moving a neutral conductor toward the globe. Another favorite is to pile up aluminum muffin tins on top of the uncharged globe, then turn on the generator. Being made of conducting material, the tins accumulate excess charge. They then repel each other and fly off the globe one by one. A quick Internet search will show many examples of what you can do with a Van de Graaff generator.","Why don’t the electrons stay on the rubber belt when they reach the upper comb?","This simulation allows you to observe negative charge accumulating on a balloon as you rub it against a sweater. You can then observe how two charged balloons interact and how they cause polarization in a wall.","Click the reset button, and start with two balloons. Charge a first balloon by rubbing it on the sweater, and then move it toward the second balloon. Why does the second balloon not move?"],"figures":[{"sourceId":"fs-id1167067031507","filename":"CNX_HSPhysics_18_01_Transferel.jpg","relativePath":"media/CNX_HSPhysics_18_01_Transferel.jpg","alt":"This figure consists of two rows, and each row is divided into three columns labeled as “Before contact”, “At contact”, and “After contact”. Each column contains two small spheres. First consider the top row: In the “Before contact” column, the left sphere is labeled “100 e superscript minus”, the right sphere is labeled “50 e superscript minus”. In the “At contact” column, the left sphere is labeled “75 e superscript minus”, the right sphere is labeled “50 e superscript minus”. An arrow points from the left sphere to the right one and is labeled “25 e superscript minus”. In the “After contact” column, the left sphere is labeled “75 e superscript minus”, the right sphere is labeled “75 e superscript minus”. Next consider the bottom row: In the “Before contact” column, the left sphere is labeled “100 p superscript plus”, the right sphere is labeled “50 p superscript plus”. In the “At contact” column, the left sphere is labeled “100 p superscript plus”, the right sphere is labeled “75 p superscript plus”. An arrow points from the right sphere to the left one and is labeled “25 e superscript minus”. In the “After contact” column, the left sphere is labeled “75 p superscript plus”, the right sphere is labeled “75 p superscript plus”."},{"sourceId":"fs-id1167067324708","filename":"CNX_HSPhysics_18_01_induction.jpg","relativePath":"media/CNX_HSPhysics_18_01_induction.jpg","alt":"This figure has four parts, each consisting of a pair of spheres adjacent to each other. Each sphere is on a short pedestal, and all spheres and pedestals are equal in size. In Parts (a) and (b), the pair of spheres are touching each other, but in Parts (c) and (d), the pair of spheres are slightly separated from each other. In Part (a), there is no charge on either sphere. In Part (b), a rod marked with plus signs is shown close to the left sphere, which in turn has minus signs along its left edge. The right sphere has plus signs along its right edge. Part (c) is similar to Part (b), except for separation between the pair of spheres. In Part (d), minus signs are aligned along the right edge of the left sphere, and plus signs are aligned along the left edge of the right sphere. There is no rod in Part (d)."},{"sourceId":"fs-id1167066842547","filename":"CNX_HSPhysics_18_01_VDG.jpg","relativePath":"media/CNX_HSPhysics_18_01_VDG.jpg","alt":"This is a diagram in which two small circles are arranged vertically and are labeled “Upper roller” and “Lower roller”. The two circles are connected by a band labeled “Rubber belt”. A comb-shaped structure touches each circle, and these structures are labeled “Upper comb” and “Lower comb”. The upper circle is in the center of a larger circle labeled “Metal sphere”, and the lower circle is enclosed in a rectangle. A bent line connects the upper comb to the larger circle, and another bent line connects the lower comb to the rectangle and to the ground below the rectangle. A series of minus signs, labeled “Electrons”, is accompanied by a series of arrows, suggesting the flow of electrons from within the rectangle and the lower circle to the upper circle and then to the larger circle."},{"sourceId":"fs-id1167067090546","filename":"CNX_HSPhysics_18_01_VDGman.jpg","relativePath":"media/CNX_HSPhysics_18_01_VDGman.jpg","alt":"This is a photograph of a man touching the large sphere of a Van de Graaff generator, causing his hair to stand on end. The picture also shows two observers, one of whom has extended his right arm toward the man touching the generator."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch18.sec01.ex01","number":"18.1.1","title":"What is the missing charge?","problem":"[Figure 18.1] shows two spheres that initially have +4 C and +8 C of charge. After an interaction (which could simply be that they touch each other), the blue sphere has +10 C of charge, and the red sphere has an unknown quantity of charge. Use the law of conservation of charge to find the final charge on the red sphere.","problemImages":[],"strategy":"The net initial charge of the system is \\({q}_{\\text{initial}} = + 4\\,\\text{C} + 8\\,\\text{C} = + 12\\,\\text{C}\\) . The net final charge of the system is \\({q}_{\\text{final}} = + 10\\,\\text{C} + {q}_{\\text{red}}\\), where \\({q}_{\\text{red}}\\) is the final charge on the red sphere. Conservation of charge tells us that \\({q}_{\\text{initial}} = {q}_{\\text{final}}\\), so we can solve for \\({q}_{\\text{red}}\\) .","solution":"Equating \\({q}_{\\text{initial}}\\) and \\({q}_{\\text{final}}\\) and solving for \\({q}_{\\text{red}}\\) gives\n\\({q}_{\\text{initial}} = {q}_{\\text{final}} + 12\\,\\text{C} = + 10\\,\\text{C} + {q}_{\\text{red.}} + 2\\,\\text{C} = {q}_{\\text{red}.}\\) The red sphere has +2 C of charge.\nTwo spheres, one blue and one red, initially have +4 C and +8 C of charge, respectively. After the two spheres interact, the blue sphere has a charge of +10 C. The law of conservation of charge allows us to find the final charge \\({q}_{\\text{red}}\\) on the red sphere.","solutionImages":[{"sourceId":"fs-id1167067023024","filename":"CNX_HSPhysics_18_01_Conservati.jpg","relativePath":"media/CNX_HSPhysics_18_01_Conservati.jpg","alt":"This figure has two rows, one below the other. The upper row is labeled “Before interaction”, and the lower row is labeled “After interaction”. Each row has a blue sphere and a red sphere next to each other. In the upper row, the blue sphere is marked as “plus 4 C” and the red sphere is marked as “plus 8 C”. In the lower row, the blue sphere is marked as “plus 10 C” and the red sphere is marked as “q subscript red = ?”"}],"solutionTables":[],"discussion":"Like all conservation laws, conservation of charge is an accounting scheme that helps us keep track of electric charge."},{"uid":"hsphys.ch18.sec01.ex02","number":"18.1.2","title":"Charging Ink Droplets","problem":"Electrically neutral ink droplets in an ink-jet printer pass through an electron beam created by an electron gun, as shown in [Figure 18.1]. Some electrons are captured by the ink droplet, so that it becomes charged. After passing through the electron beam, the net charge of the ink droplet is \\({q}_{\\text{ink}\\text{drop}} = -1\\, \\times \\,{10}^{-10}\\text{C}\\) . How many electrons are captured by the ink droplet?\nElectrons from an electron gun charge a passing ink droplet.","problemImages":[{"sourceId":"fs-id1167066970903","filename":"CNX_HSPhysics_18_01_inkdrop.jpg","relativePath":"media/CNX_HSPhysics_18_01_inkdrop.jpg","alt":"Six small purple spheres, each marked as “e superscript minus”, are arranged vertically and labeled as “electrons”. The three lowest spheres are enclosed in a rectangle, the fourth one above them is crossing the upper edge of the rectangle, and the two uppermost spheres are outside the rectangle. An arrow next to the two uppermost spheres is pointing upward, suggesting the direction of movement of the purple spheres. A much larger black sphere, labeled “Ink droplet”, is above and to the left of the column of purple spheres, and an arrow pointing toward the right suggests the direction of movement of the black sphere."}],"strategy":"A single electron carries a charge of \\({q}_{{e}^{-}} = -1.602\\, \\times \\,{10}^{-19}\\text{C}\\) . Dividing the net charge of the ink droplet by the charge \\({q}_{{e}^{-}}\\) of a single electron will give the number of electrons captured by the ink droplet.","solution":"The number n of electrons captured by the ink droplet are\n\\(n = \\frac{{q}_{\\text{ink}\\text{drop}}}{{q}_{{e}^{-}}} = \\frac{- 1\\, \\times \\,{10}^{- 10}\\text{C}}{- 1.602\\, \\times \\,{10}^{- 19}\\text{C}} = 6\\, \\times \\,{10}^{8}.\\)","solutionImages":[],"solutionTables":[],"discussion":"This is almost a billion electrons! It seems like a lot, but it is quite small compared to the number of atoms in an ink droplet, which number about \\({10}^{16}.\\) Thus, each extra electron is shared between about \\({10}^{16}/(6\\, \\times \\,{10}^{8}) \\approx {10}^{7}\\) atoms."}],"snapLabs":[{"uid":"hsphys.ch18.sec01.lab01","title":"Like and Unlike Charges","text":"This activity investigates the repulsion and attraction caused by static electrical charge.\nAdhesive tape\nNonconducting surface, such as a plastic table or chair\nInstructions\nProcedure for Part (a)\nPrepare two pieces of tape about 4 cm long. To make a handle, double over about 0.5 cm at one end so that the sticky side sticks together.\nAttach the pieces of tape side by side onto a nonmetallic surface, such as a tabletop or the seat of a chair, as shown in [Figure 18.1](a).\nPeel off both pieces of tape and hang them downward, holding them by the handles, as shown in [Figure 18.1](b). If the tape bends upward and sticks to your hand, try using a shorter piece of tape, or simply shake the tape so that it no longer sticks to your hand.\nNow slowly bring the two pieces of tape together, as shown in [Figure 18.1](c). What happens?\nProcedure for Part (b)\nStick one piece of tape on the nonmetallic surface, and stick the second piece of tape on top of the first piece, as shown in [Figure 18.1](a).\nSlowly peel off the two pieces by pulling on the handle of the bottom piece.\nGently stroke your finger along the top of the second piece of tape (i.e., the nonsticky side), as shown in [Figure 18.1](b).\nPeel the two pieces of tape apart by pulling on their handles, as shown in [Figure 18.1](c).\nSlowly bring the two pieces of tape together. What happens?","images":[{"sourceId":"fs-id1167063734271","filename":"CNX_HSPhysics_18_01_scotcha_img.jpg","relativePath":"media/CNX_HSPhysics_18_01_scotcha_img.jpg","alt":"This image has three parts. Part a shows two pieces of sticky tape attached to the edge of an arc-shaped object, with someone's fingers near the end of one tape. Part b shows someone's fingers lifting one tape piece away from the arc-shaped object, while the other tape piece remains attached to the object. Part c shows a left hand and a right hand, each holding a piece of tape from one end. Two short red arrows, each starting from the free end of a piece of tape, point toward each other."},{"sourceId":"fs-id1167067179094","filename":"CNX_HSPhysics_18_01_scotchb_img.jpg","relativePath":"media/CNX_HSPhysics_18_01_scotchb_img.jpg","alt":"This image has three parts. Part a shows two pieces of sticky tape, with one stuck over the other, and with the lower tape attached to the edge of an arc-shaped object. The two tapes are slightly separated from each other at one end. In part b, someone's hand holds the two pieces of tape from the end where they are separated, while a finger touches the other end. Part c shows two hands pulling the two pieces of tape apart."}]},{"uid":"hsphys.ch18.sec01.lab02","title":"Polarizing Tap Water","text":"This lab will demonstrate how water molecules can easily be polarized.\nPlastic object of small dimensions, such as comb or plastic stirrer\nSource of tap water\nInstructions\nProcedure\nThoroughly rub the plastic object with a dry cloth.\nOpen the faucet just enough to let a smooth filament of water run from the tap.\nMove an edge of the charged plastic object toward the filament of running water.\nWhat do you observe? What happens when the plastic object touches the water filament? Can you explain your observations?","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch18.sec01.feat01","type":"physics-in-action","title":"Measuring the Fundamental Electric Charge","text":"The American physicist Robert Millikan (1868–1953) and his student Harvey Fletcher (1884–1981) were the first to make a relatively accurate measurement of the fundamental unit of charge on the electron. They designed what is now a classic experiment performed by students. The Millikan oil-drop experiment is shown in [Figure 18.1]. The experiment involves some concepts that will be introduced later, but the basic idea is that a fine oil mist is sprayed between two plates that can be charged with a known amount of opposite charge. Some oil drops accumulate some excess negative charge when being sprayed and are attracted to the positive charge of the upper plate and repelled by the negative charge on the lower plate. By tuning the charge on these plates until the weight of the oil drop is balanced by the electric forces, the net charge on the oil drop can be determined quite precisely.\nThe oil-drop experiment involved spraying a fine mist of oil between two metal plates charged with opposite charges. By knowing the mass of the oil droplets and adjusting the electric charge on the plates, the charge on the oil drops can be determined with precision.\nMillikan and Fletcher found that the drops would accumulate charge in discrete units of about \\(-1.59\\, \\times \\,{10}^{-19}\\text{C,}\\) which is within 1 percent of the modern value of \\(-1.60\\, \\times \\,{10}^{-19}\\text{C.}\\) Although this difference may seem quite small, it is actually five times greater than the possible error Millikan reported for his results!\nBecause the charge on the electron is a fundamental constant of nature, determining its precise value is very important for all of science. This created pressure on Millikan and others after him that reveals some equally important aspects of human nature.\nFirst, Millikan took sole credit for the experiment and was awarded the 1923 Nobel Prize in physics for this work, although his student Harvey Fletcher apparently contributed in significant ways to the work. Just before his death in 1981, Fletcher divulged that Millikan coerced him to give Millikan sole credit for the work, in exchange for which Millikan promoted Fletcher’s career at Bell Labs.\nAnother great scientist, Richard Feynman, points out that many scientists who measured the fundamental charge after Millikan were reluctant to report values that differed much from Millikan’s value. History shows that later measurements slowly crept up from Millikan’s value until settling on the modern value. Why did they not immediately find the error and correct the value, asks Feynman. Apparently, having found a value higher than the much-respected value found by Millikan, scientists would look for possible mistakes that might lower their value to make it agree better with Millikan’s value. This reveals the important psychological weight carried by preconceived notions and shows how hard it is to refute them. Scientists, however devoted to logic and data they may be, are apparently just as vulnerable to this aspect of human nature as everyone else. The lesson here is that, although it is good to be skeptical of new results, you should not discount them just because they do not agree with conventional wisdom. If your reasoning is sound and your data are reliable, the conclusion demanded by the data must be seriously considered, even if that conclusion disagrees with the commonly accepted truth.\nSuppose that Millikan observed an oil drop carrying three fundamental units of charge. What would be the net charge on this oil drop?\n-4.81 × 10 -19 C\n-1.602 × 10 -19 C\n1.602 × 10 -19 C\n4.81 × 10 -19 C","images":[{"sourceId":"fs-id1167067324564","filename":"CNX_HSPhysics_18_01_Oildrop.jpg","relativePath":"media/CNX_HSPhysics_18_01_Oildrop.jpg","alt":"This figure is a two-part drawing. One part consists of two circular plates held parallel to each other, with a beam of light shining between them. Each plate has a wire attached to it. The upper plate, with a tiny hole at its center, is marked with a plus sign, and the lower plate is marked with a minus sign. A small spray bottle, labeled “Atomizer,” is held by a hand near and just above the upper plate. The hand squeezes a bulb on the Atomizer, and a spray labeled “Oil” emerges just above the upper plate. The beam of light emerges from a source labeled “Bright light.” The drawing includes a telescope-like device aimed for viewing between the circular plates. The second part of the drawing, located slightly below the first part, shows an edge-on view of the two plates. A downward pointing arrow connects the plates in the first part of the drawing to those in the second part. In the latter drawing, four vertical blue arrows point from the upper to the lower plate, and the arrow on the extreme right is labeled as E. A gray sphere between the two plates is labeled “Oil droplet.” A short red arrow, labeled F subscript E, points from the sphere to the upper plate, and another short red arrow, labeled w, points from the sphere to the lower plate."}]}],"summaryPoints":["Electric charge is a conserved quantity, which means it can be neither created nor destroyed.","Electric charge comes in two varieties, which are called positive and negative .","Charges with the same sign repel each other. Charges with opposite signs attract each other.","Charges can move easily in conducting material. Charges cannot move easily in an insulating material.","Objects can be charged in three ways: by contact, by conduction, and by induction.","Although a polarized object may be neutral, its electrical charge is unbalanced, so one side of the object has excess negative charge and the other side has an equal magnitude of excess positive charge."],"glossary":[{"term":"conductor","termVi":"Chất dẫn điện (Vật dẫn)","definition":"material through which electric charge can easily move, such as metals","definitionVi":"Vật liệu cho phép các điện tích tự do (electron) di chuyển dễ dàng bên trong nó (như đồng, bạc, nhôm).","memoryTipVi":"Kim loại dẫn điện tốt nhờ biển electron tự do."},{"term":"electron","termVi":"Êlectron (e⁻)","definition":"subatomic particle that carries one indivisible unit of negative electric charge","definitionVi":"Hạt hạ nguyên tử mang điện tích âm nguyên tố: q_e = -1.602 × 10⁻¹⁹ C.","memoryTipVi":"Sự nhiễm điện của vật rắn luôn do sự di chuyển của ELECTRON (proton nằm chặt trong hạt nhân)!"},{"term":"induction","termVi":"Sự nhiễm điện do hưởng ứng","definition":"creating an unbalanced charge distribution in an object by moving a charged object toward it (but without touching)","definitionVi":"Cách làm nhiễm điện một vật dẫn bằng cách đưa vật mang điện LẠI GẦN (không chạm vào) rồi nối đất.","memoryTipVi":"Không cần tiếp xúc trực tiếp!"},{"term":"insulator","termVi":"Chất cách điện (Điện môi)","definition":"material through which a charge does not move, such as rubber","definitionVi":"Vật liệu mà các electron bị giữ chặt vào nguyên tử, không thể di chuyển tự do (như cao su, thủy tinh, nhựa).","memoryTipVi":"Dùng làm vỏ bọc dây điện an toàn."},{"term":"law of conservation of charge","termVi":"Định luật Bảo toàn Điện tích","definition":"states that total charge is constant in any process","definitionVi":"Tổng đại số các điện tích trong một hệ cô lập luôn không đổi.","memoryTipVi":"Điện tích không tự sinh ra hay mất đi, chỉ truyền từ vật này sang vật khác."},{"term":"polarization","termVi":"Sự phân cực điện","definition":"separation of charge induced by nearby excess charge","definitionVi":"Sự dịch chuyển nhẹ của các điện tích trái dấu về hai phía đối diện trong vật cách điện khi đặt gần điện tích.","memoryTipVi":"Giải thích vì sao lược nhựa tích điện hút được mẩu giấy vụn trung hòa!"},{"term":"proton","termVi":"Prôtôn (p⁺)","definition":"subatomic particle that carries the same magnitude charge as the electron, but its charge is positive","definitionVi":"Hạt nằm trong hạt nhân mang điện tích dương nguyên tố: +1.602 × 10⁻¹⁹ C.","memoryTipVi":"Vật tích điện dương là do MẤT bớt electron, không phải nhận thêm proton!"}],"assessments":[{"uid":"hsphys.ch18.sec01.q001","sourceId":"fs-id1167063624403","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"How many types of electric charge exist?","images":[],"choices":[{"label":"a","text":"one type"},{"label":"b","text":"two types"},{"label":"c","text":"three types"},{"label":"d","text":"four types"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q002","sourceId":"fs-id1167067054982","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which are the two main electrical classifications of materials based on how easily charges can move through them?","images":[],"choices":[{"label":"a","text":"conductor and insulator"},{"label":"b","text":"semiconductor and insulator"},{"label":"c","text":"conductor and superconductor"},{"label":"d","text":"conductor and semiconductor"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q003","sourceId":"fs-id1167063424726","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—A polarized material must have a nonzero net electric charge.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q004","sourceId":"fs-id1167067200728","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Describe the force between two positive point charges that interact.","images":[],"choices":[{"label":"a","text":"The force is attractive and acts along the line joining the two point charges."},{"label":"b","text":"The force is attractive and acts tangential to the line joining the two point charges."},{"label":"c","text":"The force is repulsive and acts along the line joining the two point charges."},{"label":"d","text":"The force is repulsive and acts tangential to the line joining the two point charges."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q005","sourceId":"fs-id1167066799463","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"How does a conductor differ from an insulator?","images":[],"choices":[{"label":"a","text":"Electric charges move easily in an insulator but not in a conducting material."},{"label":"b","text":"Electric charges move easily in a conductor but not in an insulator."},{"label":"c","text":"A conductor has a large number of electrons."},{"label":"d","text":"More charges are in an insulator than in a conductor."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q006","sourceId":"fs-id1167063517236","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—Charging an object by polarization requires touching it with an object carrying excess charge.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q007","sourceId":"fs-id1167061216329","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Which equation describes conservation of charge?","images":[],"choices":[{"label":"a","text":"q initial = q final = constant"},{"label":"b","text":"q initial = q final = 0"},{"label":"c","text":"q initial - q final = 0"},{"label":"d","text":"q initial / q final = constant"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q009","sourceId":"fs-id1167063599285","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"How many protons are needed to make 1 nC of charge? 1 nC = 10 -9 C","images":[],"choices":[{"label":"a","text":"1.6 × 10 -28"},{"label":"b","text":"1.6 × 10 -10"},{"label":"c","text":"3 × 10 9"},{"label":"d","text":"6 × 10 9"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q013","sourceId":"fs-id1167063697154","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or false—A liquid can be an insulating material.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q014","sourceId":"fs-id1167063785854","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"If you dive into a pool of seawater through which an equal amount of positively and negatively charged particles is moving, will you receive an electric shock?","images":[],"choices":[{"label":"a","text":"Yes, because negatively charged particles are moving."},{"label":"b","text":"No, because positively charged particles are moving."},{"label":"c","text":"Yes, because positively and negatively charged particles are moving."},{"label":"d","text":"No, because equal amounts of positively and negatively charged particles are moving."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q015","sourceId":"fs-id1167067042629","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or false—The high-voltage wires that you see connected to tall metal-frame towers are held aloft by insulating connectors, and these wires are wrapped in an insulating material.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q016","sourceId":"fs-id1167066956865","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"By considering the molecules of an insulator, explain how an insulator can be overall neutral but carry a surface charge when polarized.","images":[],"choices":[{"label":"a","text":"Inside the insulator, the oppositely charged ends of the molecules cancel each other."},{"label":"b","text":"Inside the insulator, the oppositely charged ends of the molecules do not cancel each other."},{"label":"c","text":"The electron distribution in all the molecules shifts in every possible direction, leaving an excess of positive charge on the opposite end of each molecule."},{"label":"d","text":"The electron distribution in all the molecules shifts in a given direction, leaving an excess of negative charge on the opposite end of each molecule."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q017","sourceId":"fs-id1167061216329","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Which equation describes conservation of charge?","images":[],"choices":[{"label":"a","text":"q initial = q final = constant"},{"label":"b","text":"q initial = q final = 0"},{"label":"c","text":"q initial - q final = 0"},{"label":"d","text":"q initial / q final = constant"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q019","sourceId":"fs-id1167063599285","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"How many protons are needed to make 1 nC of charge? 1 nC = 10 -9 C","images":[],"choices":[{"label":"a","text":"1.6 × 10 -28"},{"label":"b","text":"1.6 × 10 -10"},{"label":"c","text":"3 × 10 9"},{"label":"d","text":"6 × 10 9"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q021","sourceId":"fs-id1167067266769","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A dust particle acquires a charge of -13 nC. How many excess electrons does it carry?","images":[],"choices":[{"label":"a","text":"20.8 × 10 -28 electrons"},{"label":"b","text":"20.8 × -19 electrons"},{"label":"c","text":"8.1 × 10 10 electrons"},{"label":"d","text":"8.1 × 10 19 electrons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q022","sourceId":"fs-id1167067014283","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Two identical conducting spheres are charged with a net charge of +5.0 q on the first sphere and a net charge of -8.0 q on the second sphere. The spheres are brought together, allowed to touch, and then separated. What is the net charge on each sphere now?","images":[],"choices":[{"label":"a","text":"-3.0 q"},{"label":"b","text":"-1.5 q"},{"label":"c","text":"+1.5 q"},{"label":"d","text":"+3.0 q"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q023","sourceId":"fs-id1167063451818","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A neutral hydrogen atom has one proton and one electron. If you remove the electron, what will be the leftover sign of the charge?","images":[],"choices":[{"label":"a","text":"negative"},{"label":"b","text":"positive"},{"label":"c","text":"zero"},{"label":"d","text":"neutral"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q024","sourceId":"fs-id1167067043395","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the charge on a proton?","images":[],"choices":[{"label":"a","text":"+8.99 × 10 –9 C"},{"label":"b","text":"-8.99 × 10 –9 C"},{"label":"c","text":"+ 1.60 × 10 –19 C"},{"label":"d","text":"-1.60 × 10 –19 C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q025","sourceId":"fs-id1167063852664","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or false—Carbon is more conductive than pure water.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q026","sourceId":"fs-id1167067115263","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or false—Two insulating objects are polarized. To cancel the polarization, it suffices to touch them together.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q027","sourceId":"eip-id1166848945673","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"How is the charge of the proton related to the charge of the electron?","images":[],"choices":[{"label":"a","text":"The magnitudes of charge of the proton and the electron are equal, but the charge of the proton is positive, whereas the charge of the electron is negative."},{"label":"b","text":"The magnitudes of charge of the proton and the electron are unequal, but the charge of the proton is positive, whereas the charge of the electron is negative."},{"label":"c","text":"The magnitudes of charge of the proton and the electron are equal, but the charge of the proton is negative, whereas the charge of the electron is positive."},{"label":"d","text":"The magnitudes of charge of the proton and the electron are unequal, but the charge of the proton is negative, whereas the charge of the electron is positive."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q028","sourceId":"fs-id1167067254022","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Compare the mass of the electron with the mass of the proton.","images":[],"choices":[{"label":"a","text":"The mass of the electron is about 1,000 times that of the proton."},{"label":"b","text":"The mass of the proton is about 1,000 times that of the electron."},{"label":"c","text":"The mass of the electron is about 1,836 times that of the proton."},{"label":"d","text":"The mass of the proton is about 1,836 times that of the electron."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q029","sourceId":"fs-id1167063688328","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The positive terminal of a battery is connected to one connection of a lightbulb, and the other connection of the lightbulb is connected to the negative terminal of the battery. The battery pushes charge through the circuit but does not become charged itself. Does this violate the law of conservation of charge? Explain.","images":[],"choices":[{"label":"a","text":"No, because this is a closed circuit."},{"label":"b","text":"No, because this is an open circuit."},{"label":"c","text":"Yes, because this is a closed circuit."},{"label":"d","text":"Yes, because this is an open circuit."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q031","sourceId":"fs-id1167067251333","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The students in your class count off consecutively so each student has a number. The odd-numbered students are told to act as negative charge, and the even-numbered students are told to act as positive charge. How would you organize them to represent a polarized material?","images":[],"choices":[{"label":"a","text":"The even-numbered and odd-numbered students will be arranged one after the other."},{"label":"b","text":"Two even-numbered will be followed by two odd-numbered, and so on."},{"label":"c","text":"Even-numbered students will be asked to come to the front, whereas odd-numbered students will be asked to go to the back of the class."},{"label":"d","text":"Half even-numbered and odd-numbered will come to the front, whereas half even-numbered and odd-numbered will go to the back."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q032","sourceId":"fs-id1167066793177","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"An ion of iron contains 56 protons. How many electrons must it contain if its net charge is +5 e ?","images":[],"choices":[{"label":"a","text":"five electrons"},{"label":"b","text":"51 electrons"},{"label":"c","text":"56 electrons"},{"label":"d","text":"61 electrons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q034","sourceId":"fs-id1167067200434","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A solid cube carries a charge of +25 e . You measure the charge on each face of the cube and find that each face carries +3 e of charge. Is the cube made of conducting or insulating material? Explain.","images":[],"choices":[{"label":"a","text":"The cube is made of insulating material, because all the charges are on the surface of the cube."},{"label":"b","text":"The cube is made of conducting material, because some of the charges are inside the cube."},{"label":"c","text":"The cube is made of conducting material, because all the charges are on the surface of the cube."},{"label":"d","text":"The cube is made of insulating material, because some of the charges are inside the cube."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q035","sourceId":"fs-id1167061190362","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"You have four neutral conducting spheres and a charging device that allows you to place charge q on any neutral object. You want to charge one sphere with a charge q /2 and the other three with a charge q /6 . How do you proceed?","images":[],"choices":[{"label":"a","text":"Charge one sphere with charge q . Touch it simultaneously to the three remaining neutral spheres."},{"label":"b","text":"Charge one sphere with charge q . Touch it to one other sphere to produce two spheres with charge \\(\\frac{q}{2}\\) . Touch one of these spheres to one other neutral sphere."},{"label":"c","text":"Charge one sphere with charge q . Touch it to one other sphere to produce two spheres with charge \\(\\frac{q}{2}\\) . Touch one of these spheres simultaneously to the two remaining neutral spheres."},{"label":"d","text":"Charge one sphere with charge q . Touch it simultaneously to two other neutral spheres to produce three spheres with charge q /3. Touch one of these spheres to one other neutral sphere."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q037","sourceId":"fs-id1167063426261","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or false—Conservation of charge is like balancing a budget.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q038","sourceId":"fs-id1167067105305","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or false—Although wood is an insulator, lightning can travel through a tree to reach Earth.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec01.q039","sourceId":"fs-id1167063554122","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or false—An eccentric inventor attempts to levitate by first placing a large negative charge on himself and then putting a large positive charge on the ceiling of his workshop. Instead, while he attempts to place a large negative charge on himself, his clothes fly off.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":4,"keyEquationCount":0,"subsectionCount":4,"workedExampleCount":2,"snapLabCount":2,"glossaryCount":7,"assessmentCount":30}},{"uid":"hsphys.ch18.sec02","moduleId":"m54414","number":"18.2","slug":"coulomb-s-law","title":"Coulomb's law","isIntroduction":false,"learningObjectives":["Describe Coulomb’s law verbally and mathematically","Solve problems involving Coulomb’s law"],"bilingualGuide":{"notebookSummaryVi":"Định luật Coulomb: F = k |q₁q₂| / r².","wordProblemCues":[{"phraseEn":"electrostatic force","meaningVi":"Lực tĩnh điện Coulomb","mathNotation":"F = k|q₁q₂|/r²"}],"commonTrapsVi":["Nhớ đổi đơn vị microcoulomb (1 μC = 10⁻⁶ C) và nanocoulomb (1 nC = 10⁻⁹ C) về Coulomb (C)!"]},"keyEquations":[{"name":"Coulomb’s law","formula":"\\(F = \\frac{k{q}_{1}{q}_{2}}{{r}^{2}}\\)"}],"subsections":[],"workedExamples":[{"uid":"hsphys.ch18.sec02.ex01","number":"18.2.1","title":"Using Coulomb’s law to find the force between charged objects","problem":"Suppose Coulomb measures a force of \\(20\\, \\times \\,{10}^{-6}\\text{N}\\) between the two charged spheres when they are separated by 5.0 cm. By turning the dial at the top of the torsion balance, he approaches the spheres so that they are separated by 3.0 cm. Which force does he measure now?","problemImages":[],"strategy":"Apply Coulomb’s law to the situation before and after the spheres are brought closer together. Although we do not know the charges on the spheres, we do know that they remain the same. We call these unknown but constant charges \\({q}_{1}\\) and \\({q}_{2}\\) . Because these charges appear as a product in Coulomb’s law, they form a single unknown. We thus have two equations and two unknowns, which we can solve. The first unknown is the force (which we call \\({F}_{\\text{f}}\\) ) when the spheres are 3.0 cm apart, and the second is \\({q}_{1}{q}_{2}\\) .\nUse the following notation: When the charges are 5.0 cm apart, the force is \\({F}_{\\text{i}} = 20\\, \\times \\,{10}^{-6}\\text{N}\\) and \\({r}_{\\text{i}} = 5.0\\,\\text{cm} = 0.050\\,\\text{m}\\), where the subscript i means initial . Once the charges are brought closer together, we know \\({r}_{\\text{f}} = 3.0\\,\\text{cm} = 0.030\\,\\text{m}\\), where the subscript f means final .","solution":"Coulomb’s law applied to the spheres in their initial positions gives\n\\({F}_{\\text{i}} = \\frac{k{q}_{1}{q}_{2}}{{r}_{\\text{i}}^{2.}}\\text{.}\\) Coulomb’s law applied to the spheres in their final positions gives\n\\({F}_{\\text{f}} = \\frac{k{q}_{1}{q}_{2}}{{r}_{\\text{f}}^{2.}}\\text{.}\\) Dividing the second equation by the first and solving for the final force \\({F}_{\\text{f}}\\) leads to\n\\(\\frac{{F}_{\\text{f}}}{{F}_{\\text{i}}} = \\frac{k{q}_{1}{q}_{2}/{r}_{\\text{f}}^{2}}{k{q}_{1}{q}_{2}/{r}_{\\text{i}}^{2}}\\text{.} = \\frac{{r}_{\\text{i}}^{2}}{{r}_{\\text{f}}^{2}}{F}_{\\text{f}} = {F}_{\\text{i}}\\frac{{r}_{\\text{i}}^{2}}{{r}_{\\text{f}}^{2}}\\text{.}\\) Inserting the known quantities yields\n\\({F}_{\\text{f}} = {F}_{\\text{i}}\\frac{{r}_{\\text{i}}^{2}}{{r}_{\\text{f}}^{2}} = (20\\, \\times \\,{10}^{-6}\\text{N})\\frac{{(0.050\\,\\text{m})}^{2}}{{(0.030\\,\\text{m})}^{2}} = 56\\, \\times \\,{10}^{-6}\\text{N} = 5.6\\, \\times \\,{10}^{-5}\\text{N.}\\) The force acts along the line joining the centers of the spheres. Because the same type of charge is on each sphere, the force is repulsive.","solutionImages":[],"solutionTables":[],"discussion":"As expected, the force between the charges is greater when they are 3.0 cm apart than when they are 5.0 cm apart. Note that although it is a good habit to convert cm to m (because the constant k is in SI units), it is not necessary in this problem, because the distances cancel out.\nWe can also solve for the second unknown \\(|{q}_{1}{q}_{2}|\\) . By using the first equation, we find\n\\({F}_{\\text{f}} = \\frac{k{q}_{1}{q}_{2}}{{r}_{\\text{i}}^{2}}{q}_{1}{q}_{2} = \\frac{{F}_{\\text{i}}{r}_{\\text{i}}^{2}}{k} = \\frac{(20\\, \\times \\,{10}^{-6}\\text{N}){(0.050\\,\\text{m})}^{2}}{8.99\\, \\times \\,{10}^{9}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/C}}^{\\text{2}}} = 5.6\\, \\times \\,{10}^{-18}{\\text{C}}^{2}\\) Note how the units cancel in the second-to-last line. Had we not converted cm to m, this would not occur, and the result would be incorrect. Finally, because the charge on each sphere is the same, we can further deduce that\n\\({q}_{1} = {q}_{2} = \\pm \\sqrt{5.6\\, \\times \\,{10}^{-18}{\\text{C}}^{2}} = \\pm 2.4\\,\\text{nC.}\\)"},{"uid":"hsphys.ch18.sec02.ex02","number":"18.2.2","title":"Using Coulomb’s law to find the distance between charged objects","problem":"An engineer measures the force between two ink drops by measuring their acceleration and their diameter. She finds that each member of a pair of ink drops exerts a repulsive force of \\(F = 5.5\\,\\text{mN}\\) on its partner. If each ink drop carries a charge \\({q}_{\\text{ink}\\text{drop}} = -1\\, \\times \\,{10}^{-10}\\text{C}\\), how far apart are the ink drops?","problemImages":[],"strategy":"We know the force and the charge on each ink drop, so we can solve Coulomb’s law for the distance r between the ink drops. Do not forget to convert the force into SI units: \\(F = 5.5\\,\\text{mN} = 5.5\\, \\times \\,{10}^{-3}\\text{N.}\\)","solution":"The charges in Coulomb’s law are \\({q}_{1} = {q}_{2} = {q}_{\\text{ink}\\text{drop}}^{}\\text{,}\\) so the numerator in Coulomb’s law takes the form \\({q}_{1}{q}_{2} = {q}_{\\text{ink}\\text{drop}}^{2}\\) . Inserting this into Coulomb’s law and solving for the distance r gives\n\\(F = \\frac{k{q}_{\\text{ink}\\text{drop}}^{2}}{{r}^{2}}r = \\pm \\sqrt{\\frac{k{q}_{\\text{ink}\\text{drop}}^{2}}{F}} = \\pm \\sqrt{\\frac{(8.99\\, \\times \\,{10}^{9}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/C}}^{\\text{2}}){(-1\\, \\times \\,{10}^{-10}\\text{C})}^{2}}{5.5 \\times {10}^{-3}\\text{N}}} = \\pm 1.3 \\times {10}^{-4}\\text{m}\\)\nor 130 microns (about one-tenth of a millimeter).","solutionImages":[],"solutionTables":[],"discussion":"The plus-minus sign means that we do not know which ink drop is to the right and which is to the left, but that is not important, because both ink drops are the same."}],"snapLabs":[{"uid":"hsphys.ch18.sec02.lab01","title":"Hovering plastic","text":"In this lab, you will use electrostatics to hover a thin piece of plastic in the air.\nBalloon\nLight plastic bag (e.g., produce bag from grocery store)\nInstructions\nProcedure\nCut the plastic bag to make a plastic loop about 2 inches wide.\nInflate the balloon.\nCharge the balloon by rubbing it on your clothes.\nCharge the plastic loop by placing it on a nonmetallic surface and rubbing it with a cloth.\nHold the balloon in one hand, and in the other hand hold the plastic loop above the balloon. If the loop clings too much to your hand, recruit a friend to hold the strip above the balloon with both hands. Now let go of the plastic loop, and maneuver the balloon under the plastic loop to keep it hovering in the air above the balloon.","images":[]}],"tipsAndFeatures":[],"summaryPoints":["Coulomb’s law is an inverse square law and describes the electrostatic force between particles.","The electrostatic force between charged objects is proportional to the charge on each object and inversely proportional to the distance squared between the objects.","If Coulomb’s law gives a negative result, the force is attractive; if the result is positive, the force is repulsive."],"glossary":[{"term":"Coulomb’s law","termVi":"Định luật Coulomb","definition":"describes the electrostatic force between charged objects, which is proportional to the charge on each object and inversely proportional to the square of the distance between the objects","definitionVi":"Lực tương tác tĩnh điện giữa 2 điện tích điểm: F = k·|q₁q₂| / r² (k ≈ 8.99 × 10⁹ N·m²/C²).","memoryTipVi":"Cùng dấu ĐẨY nhau, trái dấu HÚT nhau."},{"term":"inverse-square law","termVi":"Quy luật tỉ lệ nghịch bình phương khoảng cách","definition":"law that has the form of a ratio, with the denominator being the distance squared","definitionVi":"Độ lớn lực giảm theo bình phương khoảng cách (1/r²) — áp dụng cho cả lực hấp dẫn lẫn lực Coulomb.","memoryTipVi":"Khoảng cách tăng gấp 3 → Lực giảm 9 lần!"}],"assessments":[{"uid":"hsphys.ch18.sec02.q002","sourceId":"fs-id1167065941616","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Why is Coulomb’s law called an inverse-square law?","images":[],"choices":[{"label":"a","text":"because the force is proportional to the inverse of the distance squared between charges"},{"label":"b","text":"because the force is proportional to the product of two charges"},{"label":"c","text":"because the force is proportional to the inverse of the product of two charges"},{"label":"d","text":"because the force is proportional to the distance squared between charges"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q003","sourceId":"fs-id1167066105011","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A charge of -4 × 10 -9 C is a distance of 3 cm from a charge of 3 × 10 -9 C . What is the magnitude and direction of the force between them?","images":[],"choices":[{"label":"a","text":"1.2 × 10 -4 N, and the force is attractive"},{"label":"b","text":"1.2 × 10 14 N, and the force is attractive"},{"label":"c","text":"6.74 × 10 23 N, and the force is attractive"},{"label":"d","text":"3.6 × 10 -6 N, and the force is attractive"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q004","sourceId":"fs-id1167064916142","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Two charges are repelled by a force of 2.0 N. If the distance between them triples, what is the force between the charges?","images":[],"choices":[{"label":"a","text":"0.22 N"},{"label":"b","text":"0.67 N"},{"label":"c","text":"2.0 N"},{"label":"d","text":"18.0 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q005","sourceId":"fs-id1167064915347","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Two plastic spheres with uniform charge repel each other with a force of 10 N . If you remove the charge from one sphere, what will be the force between the spheres?","images":[],"choices":[{"label":"a","text":"The force will be 15 N."},{"label":"b","text":"The force will be 10 N."},{"label":"c","text":"The force will be 5 N."},{"label":"d","text":"The force will be zero (or nearly zero)."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q006","sourceId":"eip-id1166848691465","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What creates a greater magnitude of force, two charges + q a distance r apart or two charges – q the same distance apart?","images":[],"choices":[{"label":"a","text":"Two charges + q a distance r away"},{"label":"b","text":"Two charges - q a distance r away"},{"label":"c","text":"The magnitudes of forces are equal."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q007","sourceId":"eip-id1166851087585","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"In Newton’s law of universal gravitation, the force between two masses is proportional to the product of the two masses. What plays the role of mass in Coulomb’s law?","images":[],"choices":[{"label":"a","text":"the electric charge"},{"label":"b","text":"the electric dipole"},{"label":"c","text":"the electric monopole"},{"label":"d","text":"the electric quadruple"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q008","sourceId":"fs-id1167062303374","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"In terms of Coulomb’s law, why are water molecules attracted by positive and negative charges?","images":[],"choices":[{"label":"a","text":"Water molecules are neutral."},{"label":"b","text":"Water molecules have a third type of charge that is attracted by positive as well as negative charges."},{"label":"c","text":"Water molecules are polar."},{"label":"d","text":"Water molecule have either an excess of electrons or an excess of protons."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q010","sourceId":"fs-id1167066105011","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A charge of -4 × 10 -9 C is a distance of 3 cm from a charge of 3 × 10 -9 C . What is the magnitude and direction of the force between them?","images":[],"choices":[{"label":"a","text":"1.2 × 10 -4 N, and the force is attractive"},{"label":"b","text":"1.2 × 10 14 N, and the force is attractive"},{"label":"c","text":"6.74 × 10 23 N, and the force is attractive"},{"label":"d","text":"3.6 × 10 -6 N, and the force is attractive"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q011","sourceId":"fs-id1167064916142","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Two charges are repelled by a force of 2.0 N. If the distance between them triples, what is the force between the charges?","images":[],"choices":[{"label":"a","text":"0.22 N"},{"label":"b","text":"0.67 N"},{"label":"c","text":"2.0 N"},{"label":"d","text":"18.0 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q012","sourceId":"fs-id1167064937980","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Two plastic spheres with uniform charge repel each other with a force of 10 N. If you remove the charge from one sphere, what will be the force between the spheres?","images":[],"choices":[{"label":"a","text":"-5.8 × 10 -10 C"},{"label":"b","text":"The force will be 15 N."},{"label":"c","text":"The force will be 10 N."},{"label":"d","text":"The force will be 5 N."},{"label":"e","text":"The force will be zero (or nearly zero)."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q013","sourceId":"fs-id1167064701838","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Three charges are on a line. The left charge is q 1 = 2.0 nC . The middle charge is q 2 = 5.0 nC . The right charge is q 3 = - 3.0 nC . The left and right charges are 2.0 cm from the middle charge. What is the force on the middle charge?","images":[],"choices":[{"label":"a","text":"-5.6 × 10 -4 N to the left"},{"label":"b","text":"-1.12 × 10 -4 N to the left"},{"label":"c","text":"+1.12 × 10 -4 N to the right"},{"label":"d","text":"5.6 × 10 -4 N to the right"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q014","sourceId":"fs-id1167065999974","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If you double the distance between two point charges, by which factor does the force between the particles change?","images":[],"choices":[{"label":"a","text":"1/2"},{"label":"b","text":"2"},{"label":"c","text":"4"},{"label":"d","text":"1/4"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q015","sourceId":"eip-id1166850948875","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"The combined charge of all the electrons in a dime is hundreds of thousands of coulombs. Because like charges repel, what keeps the dime from exploding?","images":[],"choices":[{"label":"a","text":"The dime has an equal number of protons, with positive charge."},{"label":"b","text":"The dime has more protons than electrons, with positive charge."},{"label":"c","text":"The dime has fewer protons than electrons, with positive charge."},{"label":"d","text":"The dime is polarized, with electrons on one side and protons on the other side."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q018","sourceId":"fs-id1167065788741","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The force between two charges is 4 × 10 –9 N . If the magnitude of one charge is reduced by a factor of two and the distance between the charges is reduced by a factor of two, what is the new force between the charges?","images":[],"choices":[{"label":"a","text":"2 × 10 –9 N"},{"label":"b","text":"4 × 10 –9 N"},{"label":"c","text":"6 × 10 –9 N"},{"label":"d","text":"8 × 10 –9 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q019","sourceId":"fs-id1167065012486","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or false—Coulomb’s constant is k = 8.99 × 10 9 N·m 2 /C 2 . Newton’s gravitational constant is G = 6.67 × 10 -11 m 3 /kg⋅s 2 . This tells you about the relative strength of the electrostatic force versus that of gravity.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q020","sourceId":"fs-id1167066177095","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"An atomic nucleus contains 56 protons, for barium. Which force would this nucleus apply on an electron at a distance of 10×10 –12 m?","images":[],"choices":[{"label":"a","text":"0.65 × 10 –4 N"},{"label":"b","text":"0.02 × 10 –4 N"},{"label":"c","text":"1.3 × 10 –4 N"},{"label":"d","text":"72.8 × 10 –4 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q021","sourceId":"fs-id1167066142293","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Electrostatic forces are enormous compared to gravitational force. Why do you not notice electrostatic forces in everyday life, whereas you do notice the force due to gravity?","images":[],"choices":[{"label":"a","text":"Because there are two types of charge, but only one type of mass exists."},{"label":"b","text":"Because there is only one type of charge, but two types of mass exist."},{"label":"c","text":"Because opposite charges cancel each other, while gravity does not cancel out."},{"label":"d","text":"Because opposite charges do not cancel each other, while gravity cancels out."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec02.q022","sourceId":"fs-id1167062342543","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A small metal sphere with a net charge of 3.0 nC is touched to a second small metal sphere that is initially neutral. The spheres are then placed 20 cm apart. What is the force between the spheres?","images":[],"choices":[{"label":"a","text":"1.02 × 10 -7 N"},{"label":"b","text":"2.55 × 10 -7 N"},{"label":"c","text":"5.1 × 10 -7 N"},{"label":"d","text":"20.4 × 10 -7 N"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":1,"subsectionCount":0,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":2,"assessmentCount":18}},{"uid":"hsphys.ch18.sec03","moduleId":"m54428","number":"18.3","slug":"electric-field","title":"Electric Field","isIntroduction":false,"learningObjectives":["Calculate the strength of an electric field","Create and interpret drawings of electric fields"],"bilingualGuide":{"notebookSummaryVi":"Điện trường (E = F/q = k|Q|/r²) và quy tắc vẽ đường sức điện.","wordProblemCues":[{"phraseEn":"electric field strength","meaningVi":"Cường độ điện trường (N/C hoặc V/m)","mathNotation":"E = F / q"}],"commonTrapsVi":["Cường độ điện trường E tại một điểm chỉ phụ thuộc điện tích nguồn Q, KHÔNG phụ thuộc điện tích thử q!"]},"keyEquations":[{"name":"electric field","formula":"\\(\\vec{E} = \\frac{\\vec{F}}{{q}_{\\text{test}}}\\)"},{"name":"magnitude of electric field of point charge","formula":"\\(E = \\frac{k|Q|}{{r}^{2}}\\)"}],"subsections":[],"workedExamples":[{"uid":"hsphys.ch18.sec03.ex01","number":"18.3.1","title":"What is the charge?","problem":"Look at the drawing of the electric field in [Figure 18.3]. What is the relative strength and sign of the three charges?\nMap of electric field due to three charged particles.","problemImages":[{"sourceId":"fs-id1167067283862","filename":"CNX_HSPhysics_18_03_charges.jpg","relativePath":"media/CNX_HSPhysics_18_03_charges.jpg","alt":"This diagram shows three small circles and various curved arrows pointing toward or away from them. A circle near the top left corner is labeled “1”, another located east of it is labeled “2”, and a third located roughly south of the first circle is labeled “3”. Some curved arrows emanating from circle 1 terminate on circle 2, and other curved arrows emanating from circle 1 terminate on circle 3."}],"strategy":"We know the electric field extends out from positive charge and terminates on negative charge. We also know that the number of electric field lines that touch a charge is proportional to the charge. Charge 1 has 12 fields coming out of it. Charge 2 has six field lines going into it. Charge 3 has 12 field lines going into it.","solution":"The electric-field lines come out of charge 1, so it is a positive charge. The electric-field lines go into charges 2 and 3, so they are negative charges. The ratio of the charges is \\({q}_{1}:{q}_{2}:{q}_{3} = + 12: - 6: - 12\\) . Thus, magnitude of charges 1 and 3 is twice that of charge 2.","solutionImages":[],"solutionTables":[],"discussion":"Although we cannot determine the precise charge on each particle, we can get a lot of information from the electric field regarding the magnitude and sign of the charges and where the force on a test charge would be greatest (or least)."},{"uid":"hsphys.ch18.sec03.ex02","number":"18.3.2","title":"Electric field from doorknob","problem":"A doorknob, which can be taken to be a spherical metal conductor, acquires a static electricity charge of \\(q = -1.5\\,\\text{nC.}\\) What is the electric field 1.0 cm in front of the doorknob? The diameter of the doorknob is 5.0 cm.","problemImages":[],"strategy":"Because the doorknob is a conductor, the entire charge is distributed on the outside surface of the metal. In addition, because the doorknob is assumed to be perfectly spherical, the charge on the surface is uniformly distributed, so we can treat the doorknob as if all the charge were located at the center of the doorknob. The validity of this simplification will be proved in a later physics course. Now sketch the doorknob, and define your coordinate system. Use \\(+ x\\) to indicate the outward direction perpendicular to the door, with \\(x = 0\\) at the center of the doorknob (as shown in the figure below).\nIf the diameter of the doorknob is 5.0 cm, its radius is 2.5 cm. We want to know the electric field 1.0 cm from the surface of the doorknob, which is a distance \\(r = 2.5\\,\\text{cm} + 1.0\\,\\text{cm} = 3.5\\,\\text{cm}\\) from the center of the doorknob. We can use the equation \\(E = \\frac{k|Q|}{{r}^{2}}\\) to find the magnitude of the electric field. The direction of the electric field is determined by the sign of the charge, which is negative in this case.","solution":"Inserting the charge \\(Q = -1.5\\,\\text{nC} = -1.5\\, \\times \\,{10}^{-9}\\text{C}\\) and the distance \\(r = 3.5\\,\\text{cm} = 0.035\\,\\text{m}\\) into the equation \\(E = \\frac{k|Q|}{{r}^{2}}\\) gives\n\\(E = \\frac{k|Q|}{{r}^{2}} = \\frac{(8.99\\, \\times \\,{10}^{9}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/C}}^{\\text{2}})| - 1.5\\, \\times \\,{10}^{- 9}\\text{C}|}{{(0.035\\,\\text{m})}^{2}} = 1.1\\, \\times \\,{10}^{4}\\text{N/C.}\\) Because the charge is negative, the electric-field lines point toward the center of the doorknob. Thus, the electric field at \\(x = 3.5\\,\\text{cm}\\) is \\(( - 1.1\\, \\times \\,{10}^{4}\\text{N/C})\\bar{x}\\) .","solutionImages":[],"solutionTables":[],"discussion":"This seems like an enormous electric field. Luckily, it takes an electric field roughly 100 times stronger ( \\(3\\, \\times \\,{10}^{6}\\text{N/C}\\) ) to cause air to break down and conduct electricity. Also, the weight of an adult is about \\(70\\,\\text{kg}\\, \\times \\,9.8{\\text{m/s}}^{2} \\approx 700\\,\\text{N}\\), so why don’t you feel a force on the protons in your hand as you reach for the doorknob? The reason is that your hand contains an equal amount of negative charge, which repels the negative charge in the doorknob. A very small force might develop from polarization in your hand, but you would never notice it."}],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":["The electric field defines the force per unit charge in the space around a charge distribution.","For a point charge or a sphere of uniform charge, the electric field is inversely proportional to the square of the distance from the point charge or from the center of the sphere.","Electric-field lines never cross each other.","More force is applied to a charge in a region with many electric field lines than in a region with few electric field lines.","Electric field lines start at positive charges and point away from positive charges. They end at negative charges and point toward negative charges."],"glossary":[{"term":"electric field","termVi":"Cường độ điện trường (E = F/q)","definition":"defines the force per unit charge at all locations in space around a charge distribution","definitionVi":"Đại lượng vectơ đặc trưng cho tác dụng lực của điện trường tại một điểm: E = F / q (đơn vị N/C hoặc V/m).","memoryTipVi":"Đường sức điện đi RA khỏi điện tích dương (+) và đi VÀO điện tích âm (−)."},{"term":"test charge","termVi":"Điện tích thử (q)","definition":"positive electric charge whose with a charge magnitude so small that it does not significantly perturb any nearby charge distribution","definitionVi":"Điện tích dương rất nhỏ đặt vào điện trường để thăm dò lực mà không làm xáo trộn điện trường gốc.","memoryTipVi":"Quy ước luôn mang dấu dương (+)."}],"assessments":[{"uid":"hsphys.ch18.sec03.q001","sourceId":"fs-id1167067036765","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"When electric field lines get closer together, what does that tell you about the electric field?","images":[],"choices":[{"label":"a","text":"The electric field is inversely proportional to the density of electric field lines."},{"label":"b","text":"The electric field is directly proportional to the density of electric field lines."},{"label":"c","text":"The electric field is not related to the density of electric field lines."},{"label":"d","text":"The electric field is inversely proportional to the square root of density of electric field lines."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q002","sourceId":"fs-id1167067238734","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"If five electric-field lines come out of a +5 nC charge, how many electric-field lines should come out of a +20 nC charge?","images":[],"choices":[{"label":"a","text":"five field lines"},{"label":"b","text":"10 field lines"},{"label":"c","text":"15 field lines"},{"label":"d","text":"20 field lines"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q003","sourceId":"fs-id1167065788346","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the magnitude of the electric field from 20 cm from a point charge of q = 33 nC?","images":[],"choices":[{"label":"a","text":"7.4 × 10 3 N/C"},{"label":"b","text":"1.48 × 10 3 N / C"},{"label":"c","text":"7.4 × 10 12 N / C"},{"label":"d","text":"0"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q004","sourceId":"fs-id1167065039818","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A -10 nC charge is at the origin. In which direction does the electric field from the charge point at x + 10 cm ?","images":[],"choices":[{"label":"a","text":"The electric field points away from negative charges."},{"label":"b","text":"The electric field points toward negative charges."},{"label":"c","text":"The electric field points toward positive charges."},{"label":"d","text":"The electric field points away from positive charges."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q005","sourceId":"fs-id1167066945720","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Why can electric fields not cross each other?","images":[],"choices":[{"label":"a","text":"Many electric-field lines can exist at any given point in space."},{"label":"b","text":"No electric-field lines can exist at any given point in space."},{"label":"c","text":"Only a single electric-field line can exist at any given point in space."},{"label":"d","text":"Two electric-field lines can exist at the same point in space."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q006","sourceId":"eip-id1166848884741","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A constant electric field is (4.5 × 10 5 N/C) ŷ . In which direction is the force on a -20 nC charge placed in this field?","images":[],"choices":[{"label":"a","text":"The direction of the force is in the \\(+ \\bar{x}\\)\ndirection."},{"label":"b","text":"The direction of the force is in the \\(+ \\bar{x}\\)\ndirection."},{"label":"c","text":"The direction of the force is in the -ŷ direction."},{"label":"d","text":"The direction of the force is in the +ŷ direction."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q007","sourceId":"fs-id1167067316776","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"An arbitrary electric field passes through a box-shaped volume. There are no charges in the box. If 11 electric-field lines enter the box, how many electric-field lines must exit the box?","images":[],"choices":[{"label":"a","text":"nine electric field lines"},{"label":"b","text":"10 electric field lines"},{"label":"c","text":"11 electric field lines"},{"label":"d","text":"12 electric field lines"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q008","sourceId":"eip-id1166847407512","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"In a science-fiction movie, a villain emits a radial electric field to repulse the hero. Knowing that the hero is electrically neutral, is this possible? Explain your reasoning.","images":[],"choices":[{"label":"a","text":"No, because an electrically neutral body cannot be repelled or attracted."},{"label":"b","text":"No, because an electrically neutral body can be attracted but not repelled."},{"label":"c","text":"Yes, because an electrically neutral body can be repelled or attracted."},{"label":"d","text":"Yes, because an electrically neutral body can be repelled."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q009","sourceId":"fs-id1167065788346","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the magnitude of the electric field from 20 cm from a point charge of q = 33 nC?","images":[],"choices":[{"label":"a","text":"7.4 × 10 3 N/C"},{"label":"b","text":"1.48 × 10 3 N / C"},{"label":"c","text":"7.4 × 10 12 N / C"},{"label":"d","text":"0"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q010","sourceId":"fs-id1167065039818","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A -10 nC charge is at the origin. In which direction does the electric field from the charge point at x + 10 cm ?","images":[],"choices":[{"label":"a","text":"The electric field points away from negative charges."},{"label":"b","text":"The electric field points toward negative charges."},{"label":"c","text":"The electric field points toward positive charges."},{"label":"d","text":"The electric field points away from positive charges."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q011","sourceId":"fs-id1167067153203","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An electric field (15 N/C) ẑ applies a force (- 3 × 10 –6 N) ẑ on a particle. What is the charge on the particle?","images":[],"choices":[{"label":"a","text":"-2.0 × 10 –7 C"},{"label":"b","text":"2.0 × 10 –7 C"},{"label":"c","text":"2.0 × 10 –8 C"},{"label":"d","text":"2.0 × 10 –9 C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q012","sourceId":"fs-id1167063616752","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Two uniform electric fields are superimposed. The first electric field is \\({\\vec{\\text{E}}}_{\\text{1}}\\text{= (14}\\text{N/C)}\\bar{x}\\)\n. The second electric field is \\({\\vec{\\text{E}}}_{\\text{2}}\\text{= (7}\\text{.0 N/C)}ŷ\\)\n. With respect to the positive x axis, at which angle will a positive test charge accelerate in this combined field?","images":[],"choices":[{"label":"a","text":"27°"},{"label":"b","text":"54°"},{"label":"c","text":"90°"},{"label":"d","text":"108°"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q013","sourceId":"fs-id1167067091682","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the magnitude of the electric field 12 cm from a charge of 1.5 nC ?","images":[],"choices":[{"label":"a","text":"9.4 × 10 7 N/ C"},{"label":"b","text":"1.1 × 10 2 N/C"},{"label":"c","text":"9.4 × 10 2 N/C"},{"label":"d","text":"9.4 × 10 –2 N/C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q014","sourceId":"fs-id1167066779250","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A charge distribution has electric field lines pointing into it. What sign is the net charge?","images":[],"choices":[{"label":"a","text":"positive"},{"label":"b","text":"neutral"},{"label":"c","text":"final"},{"label":"d","text":"negative"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q015","sourceId":"eip-id1166847910090","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If five electric field lines come out of point charge q 1 and 10 electric-field lines go into point charge q 2 , what is the ratio q 1 / q 2 ?","images":[],"choices":[{"label":"a","text":"–2"},{"label":"b","text":"–1"},{"label":"c","text":"–1/2"},{"label":"d","text":"0"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q016","sourceId":"eip-id1166849318164","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or false—The electric-field lines from a positive point charge spread out radially and point outward.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q017","sourceId":"fs-id1167067183792","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The electric field a distance of 10 km from a storm cloud is 1,000 N/C . What is the approximate charge in the cloud?","images":[],"choices":[{"label":"a","text":"0.0011 C"},{"label":"b","text":"11 C"},{"label":"c","text":"110 C"},{"label":"d","text":"1,100 C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q018","sourceId":"fs-id1167067141877","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which electric field would produce a 10 N force in the + x - direction on a charge of – 10 nC ?","images":[],"choices":[{"label":"a","text":"- 1.0 × 10 9 N/C"},{"label":"b","text":"1.0 × 10 9 N/C"},{"label":"c","text":"1.0 × 10 10 N/C"},{"label":"d","text":"1.0 × 10 11 N/C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q019","sourceId":"fs-id1167067041403","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A positive charge is located at x = 0 . When a negative charge is placed at x = 10 cm, what happens to the electric field lines between the charges?","images":[],"choices":[{"label":"a","text":"The electric field lines become denser between the charges."},{"label":"b","text":"The electric field lines become denser between the charges."},{"label":"c","text":"The electric field lines remains same between the charges."},{"label":"d","text":"The electric field lines will be zero between the charges."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q020","sourceId":"fs-id1167066784885","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Point charges are located at each corner of a square with sides of 5.0 cm . The top-left charge is q 1 = 8.0 nC The top right charge is q 2 = 4.0 nC. The bottom-right charge is q 3 = 4.0 nC. The bottom-left charge is q 4 = 8.0 nC. What is the electric field at the point midway between charges q 2 and q 3 ?","images":[],"choices":[{"label":"a","text":"\\((–2.1\\,\\text{×}\\,{10}^{4}\\text{N/C})\\bar{x}\\)"},{"label":"b","text":"\\((2.3\\,\\text{×}\\,{10}^{4}\\text{N/C})\\bar{x}\\)"},{"label":"c","text":"\\((4.1\\,\\text{×}\\,{10}^{4}\\text{N/C})\\bar{x}\\)"},{"label":"d","text":"\\((4.6\\,\\text{×}\\,{10}^{4}\\text{N/C})\\bar{x}\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec03.q021","sourceId":"fs-id1167067078255","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A long straight wire carries a uniform positive charge distribution. Draw the electric field lines in a plane containing the wire at a location far from the ends of the wire. Do not worry about the magnitude of the charge on the wire.","images":[],"choices":[{"label":"a","text":"Take the wire on the x-axis, and draw electric-field lines perpendicular to it."},{"label":"b","text":"Take the wire on the x -axis, and draw electric-field lines parallel to it."},{"label":"c","text":"Take the wire on the y-axis, and draw electric-field lines along it."},{"label":"d","text":"Take the wire on the z-axis, and draw electric-field lines along it."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":2,"subsectionCount":0,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":2,"assessmentCount":21}},{"uid":"hsphys.ch18.sec04","moduleId":"m54426","number":"18.4","slug":"electric-potential","title":"Electric Potential","isIntroduction":false,"learningObjectives":["Explain the similarities and differences between electric potential energy and gravitational potential energy","Calculate the electric potential difference between two point charges and in a uniform electric field"],"bilingualGuide":{"notebookSummaryVi":"Thế năng điện (PE) và Hiệu điện thế / Điện thế (V = ΔPE / q, đơn vị Volt).","wordProblemCues":[{"phraseEn":"potential difference (voltage)","meaningVi":"Hiệu điện thế U (Volt)","mathNotation":"ΔV = ΔPE / q"}],"commonTrapsVi":["Với điện trường đều giữa 2 bản phẳng: E = V / d (1 V/m = 1 N/C)."]},"keyEquations":[{"name":"change in electric potential energy for a charge that moves in a constant electric field","formula":"\\(\\Delta {U}_{\\text{E}} = - qE({x}_{\\text{f}} - {x}_{\\text{i}})\\)"},{"name":"electric potential energy of a charge a distance r from a point charge or sphere of uniform charge","formula":"\\({U}_{\\text{E}} = \\frac{kQq}{r}\\)"},{"name":"definition of electric potential","formula":"\\(V = \\frac{{U}_{\\text{E}}}{q}\\)"},{"name":"change in electric potential for a charge that moves in a constant electric field","formula":"\\(\\Delta V = - E({x}_{\\text{f}} - {x}_{\\text{i}})\\)"},{"name":"electric potential of a charge a distance r from a point charge or sphere of uniform charge","formula":"\\(V = \\frac{kQ}{r}\\)"}],"subsections":[{"uid":"hsphys.ch18.sec04.sub01","title":"Electric Potential","summaryVi":null,"paragraphs":["Recall that to find the force applied by a fixed charge Q on any arbitrary test charge q , it was convenient to define the electric field, which is the force per unit charge applied by Q on any test charge that we place in its electric field. The same Strategy is used here with electric potential energy: We now define the electric potential V , which is the electric potential energy per unit charge.","Normally, the electric potential is simply called the potential or voltage . The units for the potential are J/C, which are given the name volt (V) after the Italian physicist Alessandro Volta (1745–1827). From the equation \\({U}_{\\text{E}} = k{q}_{1}{q}_{2}/r\\), the electric potential a distance r from a point charge \\({q}_{1}\\) is","This equation gives the energy required per unit charge to bring a charge \\({q}_{2}\\) from infinity to a distance r from a point charge \\({q}_{1}\\text{.}\\) Mathematically, this is written as","Note that this equation actually represents a difference in electric potential. However, because the second term is zero, it is normally not written, and we speak of the electric potential instead of the electric potential difference , or we just say the potential difference, or voltage). Below, when we consider the electric potential energy per unit charge between two points not infinitely far apart, we speak of electric potential difference explicitly. Just remember that electric potential and electric potential difference are really the same thing; the former is used just when the electric potential energy is zero in either the initial or final charge configuration.","Coming back now to the electric potential a distance r from a point charge \\({q}_{1}\\), note that \\({q}_{1}\\) can be any arbitrary point charge, so we can drop the subscripts and simply write","Now consider the electric potential near a group of charges q 1 , q 2 , and q 3 , as drawn in [Figure 18.4]. The electric potential is derived by considering the electric field. Electric fields follow the principle of superposition and can be simply added together, so the electric potential from different charges also add together. Thus, the electric potential of a point near a group of charges is","where \\({r}_{1},{r}_{2},{r}_{3},…,\\) are the distances from the center of charges \\({q}_{1},{q}_{2},{q}_{3},…\\) to the point of interest, as shown in [Figure 18.4].","Now let’s consider the electric potential in a uniform electric field. From the equation \\(\\Delta {U}_{\\text{E}} = - qE({x}_{\\text{f}} - {x}_{\\text{i}})\\), we see that the potential difference in going from \\({x}_{\\text{i}}\\) to \\({x}_{\\text{f}}\\) in a uniform electric field E is","Notice that a positive charge in a region with high potential will experience a force pushing it toward regions of lower potential. In this sense, potential is like pressure for fluids. Imagine a pipe containing fluid, with the fluid at one end of the pipe under high pressure and the fluid at the other end of the pipe under low pressure. If nothing prevents the fluid from flowing, it will flow from the high-pressure end to the low-pressure end. Likewise, a positive charge that is free to move will move from a region with high potential to a region with lower potential."],"figures":[{"sourceId":"fs-id1167065996896","filename":"CNX_HSPhysics_18_04_groupcha.jpg","relativePath":"media/CNX_HSPhysics_18_04_groupcha.jpg","alt":"This figure shows three small blue spheres distributed around a much smaller red sphere. One blue sphere, labeled “q subscript 1”, lies roughly northwest of the red sphere, and an arrow labeled “r subscript 1” points from the blue sphere to the red one. A second blue sphere, labeled “q subscript 2”, lies roughly southwest of the red sphere, and an arrow labeled “r subscript 2” points from this blue sphere to the red one. The third blue sphere, labeled “q subscript 3”, lies directly south of the red sphere, and an arrow labeled “r subscript 3” points from this blue sphere to the red one."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch18.sec04.ex01","number":"18.4.1","title":"X-ray Tube","problem":"Dentists use X-rays to image their patients’ teeth and bones. The X-ray tubes that generate X-rays contain an electron source separated by about 10 cm from a metallic target. The electrons are accelerated from the source to the target by a uniform electric field with a magnitude of about 100 kN/C, as drawn in [Figure 18.4]. When the electrons hit the target, X-rays are produced. (a) What is the potential difference between the electron source and the metallic target? (b) What is the kinetic energy of the electrons when they reach the target, assuming that the electrons start at rest?\nIn an X-ray tube, a large current flows through the electron source, causing electrons to be ejected from the electron source. The ejected electrons are accelerated toward the target by the electric field. When they strike the target, X-rays are produced.\nStrategy FOR (A)\nUse the equation \\(\\Delta V = - E({x}_{\\text{f}} - {x}_{\\text{i}})\\) to find the potential difference given a constant electric field. Define the source position as \\({x}_{\\text{i}} = 0\\) and the target position as \\({x}_{\\text{f}} = 10\\,\\text{cm}\\) . To accelerate the electrons in the positive x direction, the electric field must point in the negative x direction. This way, the force \\(F = qE\\) on the electrons will point in the positive x direction, because both q and E are negative. Thus, \\(E = - 100\\, \\times \\,{10}^{3}\\text{N/C}\\) .","problemImages":[{"sourceId":"fs-id1167064981494","filename":"CNX_HSPhysics_18_04_x-raytube.jpg","relativePath":"media/CNX_HSPhysics_18_04_x-raytube.jpg","alt":"This diagram shows a vertically oriented ellipse labeled “Electron source” on the left, and a trapezoid labeled “Target” on the right. Between them, in the middle section of the diagram, there are four tiny spheres labeled “Electrons”, each of which has a short, rightward pointing arrow attached to it. Five long, horizontal arrows point from the trapezoid to the ellipse, and a label between them says “Electric field”. Near the middle of the left edge of the trapezoid is a yellow circle from which emerge three long, orange, wavy lines, as well as a number of short yellow and red lines. The long wavy lines are labeled “X-rays”."}],"strategy":null,"solution":"Solution for (a)\nUsing \\({x}_{\\text{i}} = 0\\) and \\({x}_{\\text{f}} = 10\\,\\text{cm} = 0.10\\,\\text{m}\\), the equation \\(\\Delta V = - E({x}_{\\text{f}} - {x}_{\\text{i}})\\) tells us that the potential difference between the electron source and the target is\n\\(\\Delta V = - E({x}_{\\text{f}} - {x}_{\\text{i}}) = - ( - 100\\, \\times \\,{10}^{3}\\text{N/C})(0.10\\,\\text{m} - 0) = + 10\\,\\text{kV.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The potential difference is positive, so the energy per unit positive charge is higher at the target than at the source. This means that free positive charges would fall from the target to the source. However, electrons are negative charges, so they accelerate from the source toward the target, gaining kinetic energy as they go."},{"uid":"hsphys.ch18.sec04.ex02","number":"18.4.2","title":"Electric Potential Energy of Doorknob and Dust Speck","problem":"Consider again the doorknob from the example in the previous section. The doorknob is treated as a spherical conductor with a uniform static charge \\({q}_{1} = -1.5\\,\\text{nC}\\) on its surface. What is the electric potential energy between the doorknob and a speck of dust carrying a charge \\({q}_{2} = 0.20\\,\\text{nC}\\) at 1.0 cm from the front surface of the doorknob? The diameter of the doorknob is 5.0 cm.","problemImages":[{"sourceId":"fs-id1167066112870","filename":"CNX_HSPhysics_18_04_Doorknob_img.jpg","relativePath":"media/CNX_HSPhysics_18_04_Doorknob_img.jpg","alt":"This diagram shows the edge of a door in cross-section and a doorknob attached to it. Two axes, perpendicular to each other, originate from the center of the doorknob and point away from it. The horizontal axis is labeled “plus x circumflexΣ and the vertical axis is labeled “plus y circumflex”. A dot on the horizontal axis beyond the doorknob is labeled “Speck of dust”, and a second label that gives the equation “x = 3.5 cm”."}],"strategy":"As we did in the previous section, we treat the charge as if it were concentrated at the center of the doorknob. Again, as you will be able to validate in later physics classes, we can make this simplification, because the charge is uniformly distributed over the surface of the spherical object. Make a sketch of the situation and define a coordinate system, as shown in the image below. We use \\(+ x\\) to indicate the outward direction perpendicular to the door, with \\(x = 0\\) at the center of the doorknob. If the diameter of the doorknob is 5.0 cm, its radius is 2.5 cm. Thus, the speck of dust 1.0 cm from the surface of the doorknob is a distance \\(r = 2.5\\,\\text{cm} + 1.0\\,\\text{cm} = 3.5\\,\\text{cm}\\) from the center of the doorknob. To solve this problem, use the equation \\({U}_{\\text{E}} = k{q}_{1}{q}_{2}/r\\) .","solution":"The charge on the doorknob is \\({q}_{1} = -1.5\\,\\text{nC} = -1.5\\, \\times \\,{10}^{-9}\\text{C,}\\) and the charge on the speck of dust is \\({q}_{2} = 0.20\\,\\text{nC} = 2.0\\, \\times \\,{10}^{-10}\\text{C}\\) . The distance \\(r = 3.5\\,\\text{cm} = 0.035\\,\\text{m}\\) . Inserting these values into the equation \\({U}_{\\text{E}} = k{q}_{1}{q}_{2}/r\\) gives\n\\({U}_{E} = \\frac{k{q}_{1}{q}_{2}}{r} = \\frac{(8.99\\, \\times \\,{10}^{9}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/C}}^{\\text{2}})( - 1.5\\, \\times \\,{10}^{-9}\\text{C})(2.0\\, \\times \\,{10}^{-10}\\text{C})}{(0.035\\,\\text{m})} = -7.7\\, \\times \\,{10}^{-8}\\text{J}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The energy is negative, which means that the energy will decrease that is, get even more negative as the speck of dust approaches the doorknob. This helps explain why dust accumulates on objects that carry a static charge. However, note that insulators normally collect more static charge than conductors, because any charge that accumulates on insulators cannot move about on the insulator to find a way to escape. They must simply wait to be removed by some passing moist speck of dust or other host."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch18.sec04.feat01","type":"tip","title":"Tips for Success","text":"Notice from the equation \\(\\Delta V = - E({x}_{\\text{f}} - {x}_{\\text{i}})\\) that the electric field can be written as\n\\(E = \\frac{\\Delta V}{{x}_{\\text{f}} - {x}_{\\text{i}}}\\) which means that the electric field has units of V/m. Thus, if you know the potential difference between two points, calculating the electric field is very simple—you simply divide the potential difference by the distance!","images":[]},{"uid":"hsphys.ch18.sec04.feat02","type":"physics-in-action","title":"Electric Animals","text":"Many animals generate and/or detect electric fields. This is useful for activities such as hunting, defense, navigation, communication, and mating. Because salt water is a relatively good conductor, electric fish have evolved in all the world’s oceans. These fish have intrigued humans since the earliest times. In the nineteenth century, parties were even organized where the main attraction was getting a jolt from an electric fish! Scientists also studied electric fish to learn about electricity. Alessandro Volta based his research that led to batteries in 1799 on electric fish. He even referred to batteries as artificial electric organs, because he saw them as imitations of the electric organs of electric fish.\nAnimals that generate electricity are called electrogenic and those that detect electric fields are called electroreceptive . Most fish that are electrogenic are also electroreceptive. One of the most well-known electric fish is the electric eel (see [Figure 18.4]), which is both electrogenic and electroreceptive. These fish have three pairs of organs that produce the electric charge: the main organ, Hunter’s organ, and Sach’s organ. Together, these organs account for more than 80percent of the fish’s body.\nElectric eels can produce electric discharges of much greater voltage than what you would get from a standard wall socket. These discharges can stun or even kill their prey. They also use low-intensity discharges to navigate. The electric fields they generate reflect off nearby obstacles or animals and are then detected by electroreceptors in the eel’s skin. The three organs that produce electricity contain electrolytes, which are substances that ionize when dissolved in water (or other liquids). An ionized atom or molecule is one that has lost or gained at least one electron, so it carries a net charge. Thus, a liquid solution containing an electrolyte conducts electricity, because the ions in the solution can move if an electric field is applied.\nTo produce large discharges, the main organ is used. It contains approximately 6,000 rows of electroplaques connected in a long chain. Connected this way, the voltage between electroplaques adds up, creating a large final voltage. Each electroplaque consists of a column of cells controlled by an excitor nerve. When triggered by the excitor nerve, the electroplaques allow ionized sodium to flow through them, creating a potential difference between electroplaques. These potentials add up, and a large current can flow through the electrolyte.\nThis geometry is reflected in batteries, which also use stacks of plates to produce larger potential differences.\nAn electric eel in its natural environment. (credit: Steven G. Johnson)\nIf an electric eel produces 1,000 V, which voltage is produced by each electroplaque in the main organ?\n0.17 mV\n1.7 mV\n17 mV\n170 mV","images":[{"sourceId":"fs-id1167065978554","filename":"CNX_HSPhysics_18_04_eleceel.jpg","relativePath":"media/CNX_HSPhysics_18_04_eleceel.jpg","alt":"This is a photograph showing the head of an electric eel just above water, next to the leaves of a plant growing in the water."}]}],"summaryPoints":["Electric potential energy is a concept similar to gravitational potential energy: It is the potential that charges have to do work by virtue of their positions relative to each other.","Electric potential is the electric potential energy per unit charge.","The potential is always measured between two points, where one point may be at infinity.","Positive charges move from regions of high potential to regions of low potential.","Negative charges move from regions of low potential to regions of high potential."],"glossary":[{"term":"electric potential","termVi":"Điện thế / Hiệu điện thế (V = U_e / q)","definition":"the electric potential energy per unit charge","definitionVi":"Thế năng điện trên một đơn vị điện tích (đơn vị Volt, 1 V = 1 J/C).","memoryTipVi":"Phân biệt Điện thế V (Vôn) với Thế năng điện PE (Jun)!"},{"term":"electric potential energy","termVi":"Thế năng điện (U_e)","definition":"the work that a charge can do by virtue of its position in an electric field","definitionVi":"Năng lượng dự trữ của một hệ điện tích do vị trí của chúng trong điện trường (đơn vị Joule, J).","memoryTipVi":"U_e = q · V."}],"assessments":[{"uid":"hsphys.ch18.sec04.q001","sourceId":"fs-id1167065880337","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Gravitational potential energy is the potential for two masses to do work by virtue of their positions with respect to each other. What is the analogous definition of electric potential energy?","images":[],"choices":[{"label":"a","text":"Electric potential energy is the potential for two charges to do work by virtue of their positions with respect to the origin point."},{"label":"b","text":"Electric potential energy is the potential for two charges to do work by virtue of their positions with respect to infinity."},{"label":"c","text":"Electric potential energy is the potential for two charges to do work by virtue of their positions with respect to each other."},{"label":"d","text":"Electric potential energy is the potential for single charges to do work by virtue of their positions with respect to their final positions."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q002","sourceId":"fs-id1167064893209","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"A negative charge is 10 m from a positive charge. Where would you have to move the negative charge to increase the potential energy of the system?","images":[],"choices":[{"label":"a","text":"The negative charge should be moved closer to the positive charge."},{"label":"b","text":"The negative charge should be moved farther away from the positive charge."},{"label":"c","text":"The negative charge should be moved to infinity."},{"label":"d","text":"The negative charge should be placed just next to the positive charge."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q003","sourceId":"fs-id1167066120778","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the electric potential 10 cm from a -10 nC charge?","images":[],"choices":[{"label":"a","text":"9.0 × 10 2 V"},{"label":"b","text":"9.0 × 10 3 V"},{"label":"c","text":"9.0 × 10 4 V"},{"label":"d","text":"9.0 × 10 5 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q004","sourceId":"fs-id1167066155694","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"An electron accelerates from 0 to 10 × 10 4 m/s in an electric field. Through what potential difference did the electron travel? The mass of an electron is 9.11 × 10 –31 kg, and its charge is -1.60 × 10 –19 C.","images":[],"choices":[{"label":"a","text":"29 mV"},{"label":"b","text":"290 mV"},{"label":"c","text":"2,900 mV"},{"label":"d","text":"29 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q005","sourceId":"fs-id1167064579901","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or false—The potential from a group of charges is the sum of the potentials from each individual charge.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q006","sourceId":"eip-id1166849876539","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or false—The characteristics of an electric field make it analogous to the gravitational field near the surface of Earth.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q008","sourceId":"fs-id1167064861221","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"What is the relationship between voltage and energy? More precisely, what is the relationship between potential difference and electric potential?","images":[],"choices":[{"label":"a","text":"Voltage is the energy per unit mass at some point in space."},{"label":"b","text":"Voltage is the energy per unit length in space."},{"label":"c","text":"Voltage is the energy per unit charge at some point in space."},{"label":"d","text":"Voltage is the energy per unit area in space."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q009","sourceId":"eip-id1166847293071","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Three parallel plates are stacked above each other, with a separation between each plate. If the potential difference between the first two plates is ΔV 1 and the potential between the second two plates is Δ V 2 , what is the potential difference between the first and the third plates?","images":[],"choices":[{"label":"a","text":"Δ V 3 = Δ V 2 + Δ V 1"},{"label":"b","text":"Δ V 3 = Δ V 2 - Δ V 1"},{"label":"c","text":"Δ V 3 = Δ V 2 / Δ V 1"},{"label":"d","text":"Δ V 3 = Δ V 2 ×Δ V 1"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q010","sourceId":"fs-id1167066120778","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the electric potential 10 cm from a -10 nC charge?","images":[],"choices":[{"label":"a","text":"9.0 × 10 2 V"},{"label":"b","text":"9.0 × 10 3 V"},{"label":"c","text":"9.0 × 10 4 V"},{"label":"d","text":"9.0 × 10 5 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q011","sourceId":"fs-id1167066155694","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An electron accelerates from 0 to 10 × 10 4 m/s in an electric field. Through what potential difference did the electron travel? The mass of an electron is 9.11 × 10 –31 kg, and its charge is -1.60 × 10 –19 C.","images":[],"choices":[{"label":"a","text":"29 mV"},{"label":"b","text":"290 mV"},{"label":"c","text":"2,900 mV"},{"label":"d","text":"29 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q012","sourceId":"fs-id1167066028542","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"You move a charge q from r i = 20 cm to r f = 40 cm from a fixed charge Q = 10 nC. What is the difference in potential for these two positions?","images":[],"choices":[{"label":"a","text":"-2.2 × 10 2 V"},{"label":"b","text":"-1.7 × 10 3 V"},{"label":"c","text":"-2.2 × 10 4 V"},{"label":"d","text":"-1.7 × 10 2 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q013","sourceId":"fs-id1167062509447","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"How much work is required from an outside agent to move an electron from x i = 0 to x f = 20 cm in an electric field \\((50\\text{N/C})\\bar{x}\\)\n?","images":[],"choices":[{"label":"a","text":"1.6 × 10 -15 J"},{"label":"b","text":"1.6 × 10 -16 J"},{"label":"c","text":"1.6 × 10 -20 J"},{"label":"d","text":"1.6 × 10 -18 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q014","sourceId":"fs-id1167065913781","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the potential at 1.0 m from a point charge Q = - 25 nC?","images":[],"choices":[{"label":"a","text":"6.6 × 10 2 V"},{"label":"b","text":"-2.3 × 10 2 V"},{"label":"c","text":"-6.6 × 10 2 V"},{"label":"d","text":"2.3 × 10 2 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q015","sourceId":"fs-id1167064529156","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Increasing the distance by a factor of two from a point charge will change the potential by a factor of how much?","images":[],"choices":[{"label":"a","text":"2"},{"label":"b","text":"4"},{"label":"c","text":"1/2"},{"label":"d","text":"1/4"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q016","sourceId":"eip-id1166851365187","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or false— Voltage is the common word for potential difference, because this term is more descriptive than potential difference.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q017","sourceId":"fs-id1167064778490","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The energy required to bring a charge q = - 8.8 nC from far away to 5.5 cm from a point charge Q is 13 mJ. What is the potential at the final position of q ?","images":[],"choices":[{"label":"a","text":"-112 MV"},{"label":"b","text":"-1.5 MV"},{"label":"c","text":"-0.66 MV"},{"label":"d","text":"+1.5 MV"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q018","sourceId":"fs-id1167065734950","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How is electric potential related to electric potential energy?","images":[],"choices":[{"label":"a","text":"Electric potential is the electric potential energy per unit mass at a given position in space."},{"label":"b","text":"Electric potential is the electric potential energy per unit length at a given position in space. This relation is not dimensionally correct."},{"label":"c","text":"Electric potential is the electric potential energy per unit area in space."},{"label":"d","text":"Electric potential is the electric potential energy per unit charge at a given position in space."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q019","sourceId":"fs-id1167065893807","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"If it takes 10 mJ to move a charge q from x i = 25 cm to x f = - 25 cm in an electric field of \\((20\\text{N/C})\\bar{x}\\text{,}\\) what is the charge q ?","images":[],"choices":[{"label":"a","text":"-1.0 mC"},{"label":"b","text":"+0.25 mC"},{"label":"c","text":"+ 1.0 mC"},{"label":"d","text":"+400 mC"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q021","sourceId":"fs-id1167066025391","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A square grid has charges of Q = 10 nC are each corner. The sides of the square at 10 cm . How much energy does it require to bring a q = 1.0 nC charge from very far away to the point at the center of this square?","images":[],"choices":[{"label":"a","text":"1.3 × 10 -6 J"},{"label":"b","text":"2.5 × 10 -6 J"},{"label":"c","text":"3.8 × 10 -6 J"},{"label":"d","text":"5.1 × 10 -6 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec04.q022","sourceId":"fs-id1167064919293","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"How are potential difference and electric-field strength related for a constant electric field?","images":[],"choices":[{"label":"a","text":"The magnitude of electric-field strength is equivalent to the potential divided by the distance."},{"label":"b","text":"The magnitude of electric-field strength is equivalent to the product of the electric potential and the distance."},{"label":"c","text":"The magnitude of electric-field strength is equivalent to the difference between magnitude of the electric potential and the distance."},{"label":"d","text":"The magnitude of electric-field strength is equivalent to the sum of the magnitude of the electric potential and the distance."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":5,"subsectionCount":1,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":2,"assessmentCount":20}},{"uid":"hsphys.ch18.sec05","moduleId":"m63179","number":"18.5","slug":"capacitors-and-dielectrics","title":"Capacitors and Dielectrics","isIntroduction":false,"learningObjectives":["Calculate the energy stored in a charged capacitor and the capacitance of a capacitor","Explain the properties of capacitors and dielectrics"],"bilingualGuide":{"notebookSummaryVi":"Tụ điện phẳng (C = Q/V = κε₀A/d), chất điện môi và năng lượng điện trường trong tụ điện (E_cap = ½CV²).","wordProblemCues":[{"phraseEn":"capacitance (Farad)","meaningVi":"Điện dung của tụ điện (F)","mathNotation":"C = Q / V"}],"commonTrapsVi":["Điện dung C phụ thuộc cấu tạo hình học của tụ (A, d, κ), KHÔNG phụ thuộc vào Q hay V!"]},"keyEquations":[{"name":"capacitance","formula":"\\(C = \\frac{Q}{V}\\)"},{"name":"energy stored in a capacitor","formula":"\\({U}_{E} = \\frac{1}{2}C{V}^{2}\\)"},{"name":"capacitance of a parallel-plate capacitor","formula":"\\(C = κ{ε}_{0}\\frac{A}{d}\\)"}],"subsections":[{"uid":"hsphys.ch18.sec05.sub01","title":"Capacitors","summaryVi":null,"paragraphs":["Consider again the X-ray tube discussed in the previous sample problem. How can a uniform electric field be produced? A single positive charge produces an electric field that points away from it, as in [Figure 18.3]. This field is not uniform, because the space between the lines increases as you move away from the charge. However, if we combine a positive and a negative charge, we obtain the electric field shown in [Figure 18.3](a). Notice that, between the charges, the electric field lines are more equally spaced.","What happens if we place, say, five positive charges in a line across from five negative charges, as in [Figure 18.5]? Now the region between the lines of charge contains a fairly uniform electric field.","We can extend this idea even further and into two dimensions by placing two metallic plates face to face and charging one with positive charge and the other with an equal magnitude of negative charge. This can be done by connecting one plate to the positive terminal of a battery and the other plate to the negative terminal, as shown in [Figure 18.5]. The electric field between these charged plates will be extremely uniform.","Let’s think about the work required to charge these plates. Before the plates are connected to the battery, they are neutral—that is, they have zero net charge. Placing the first positive charge on the left plate and the first negative charge on the right plate requires very little work, because the plates are neutral, so no opposing charges are present. Now consider placing a second positive charge on the left plate and a second negative charge on the right plate. Because the first two charges repel the new arrivals, a force must be applied to the two new charges over a distance to put them on the plates. This is the definition of work, which means that, compared with the first pair, more work is required to put the second pair of charges on the plates. To place the third positive and negative charges on the plates requires yet more work, and so on. Where does this work come from? The battery! Its chemical potential energy is converted into the work required to separate the positive and negative charges.","Although the battery does work, this work remains within the battery-plate system. Therefore, conservation of energy tells us that, if the potential energy of the battery decreases to separate charges, the energy of another part of the system must increase by the same amount. In fact, the energy from the battery is stored in the electric field between the plates. This idea is analogous to considering that the potential energy of a raised hammer is stored in Earth’s gravitational field. If the gravitational field were to disappear, the hammer would have no potential energy. Likewise, if no electric field existed between the plates, no energy would be stored between them.","If we now disconnect the plates from the battery, they will hold the energy. We could connect the plates to a lightbulb, for example, and the lightbulb would light up until this energy was used up. These plates thus have the capacity to store energy. For this reason, an arrangement such as this is called a capacitor . A capacitor is an arrangement of objects that, by virtue of their geometry, can store energy an electric field.","Various real capacitors are shown in [Figure 18.5]. They are usually made from conducting plates or sheets that are separated by an insulating material. They can be flat or rolled up or have other geometries.","The capacity of a capacitor is defined by its capacitance C , which is given by","where Q is the magnitude of the charge on each capacitor plate, and V is the potential difference in going from the negative plate to the positive plate. This means that both Q and V are always positive, so the capacitance is always positive. We can see from the equation for capacitance that the units of capacitance are C/V, which are called farads (F) after the nineteenth-century English physicist Michael Faraday.","The equation \\(C = Q/V\\) makes sense: A parallel-plate capacitor (like the one shown in [Figure 18.5]) the size of a football field could hold a lot of charge without requiring too much work per unit charge to push the charge into the capacitor. Thus, Q would be large, and V would be small, so the capacitance C would be very large. Squeezing the same charge into a capacitor the size of a fingernail would require much more work, so V would be very large, and the capacitance would be much smaller.","Although the equation \\(C = Q/V\\) makes it seem that capacitance depends on voltage, in fact it does not. For a given capacitor, the ratio of the charge stored in the capacitor to the voltage difference between the plates of the capacitor always remains the same. Capacitance is determined by the geometry of the capacitor and the materials that it is made from. For a parallel-plate capacitor with nothing between its plates, the capacitance is given by","where A is the area of the plates of the capacitor and d is their separation. We use \\({C}_{0}\\) instead of C , because the capacitor has nothing between its plates (in the next section, we’ll see what happens when this is not the case). The constant \\({ε}_{0}\\text{,}\\) read epsilon zero is called the permittivity of free space , and its value is","Coming back to the energy stored in a capacitor, we can ask exactly how much energy a capacitor stores. If a capacitor is charged by putting a voltage V across it for example, by connecting it to a battery with voltage V —the electrical potential energy stored in the capacitor is","Notice that the form of this equation is similar to that for kinetic energy, \\(K = \\frac{1}{2}m{v}^{{2}^{}}\\) .","In this simulation , you are presented with a parallel-plate capacitor connected to a variable-voltage battery. The battery is initially at zero volts, so no charge is on the capacitor. Slide the battery slider up and down to change the battery voltage, and observe the charges that accumulate on the plates. Display the capacitance, top-plate charge, and stored energy as you vary the battery voltage. You can also display the electric-field lines in the capacitor. Finally, probe the voltage between different points in this circuit with the help of the voltmeter.","True or false— In a capacitor, the stored energy is always positive, regardless of whether the top plate is charged with negative or positive charge."],"figures":[{"sourceId":"fs-id1167064908013","filename":"CNX_HSPhysics_18_05_embryonic.jpg","relativePath":"media/CNX_HSPhysics_18_05_embryonic.jpg","alt":"This diagram shows five red dots forming a vertical column on the left side and five blue dots forming a second vertical column on the right side. Each red dot is marked with a “plus” symbol, and each blue dot is marked with a “minus” symbol. Surrounding these dots are small arrows pointing in various directions. Between the two columns of dots, most of the arrows point rightward, from the red dots toward the blue ones. The arrows around each red dot point away from it, and most arrows around each blue dot point toward it."},{"sourceId":"fs-id1167065985058","filename":"CNX_HSPhysics_18_05_parallelca.jpg","relativePath":"media/CNX_HSPhysics_18_05_parallelca.jpg","alt":"This figure shows two parallel strips in vertical orientation connected to the terminals of a battery. The strip on the left has a series of “plus” signs and is labeled “plus Q”. It is connected to the battery terminal marked with a “plus” sign. The strip on the right has a series of “minus” signs and is labeled “minus Q”. It is connected to the battery terminal marked with a “minus” sign. Between the strips is a series of horizontal lines, and below these lines is a label that says, “E is proportional to Q”, using a proportionality sign."},{"sourceId":"fs-id1167062369067","filename":"CNX_HSPhysics_18_05_capacitors.jpg","relativePath":"media/CNX_HSPhysics_18_05_capacitors.jpg","alt":"This is a photograph showing seven small capacitors, of varying shapes and colors, usually found in electronic circuits."}],"tables":[]},{"uid":"hsphys.ch18.sec05.sub02","title":"Dielectrics","summaryVi":null,"paragraphs":["Before working through some sample problems, let’s look at what happens if we put an insulating material between the plates of a capacitor that has been charged and then disconnected from the charging battery, as illustrated in [Figure 18.5]. Because the material is insulating, the charge cannot move through it from one plate to the other, so the charge Q on the capacitor does not change. An electric field exists between the plates of a charged capacitor, so the insulating material becomes polarized, as shown in the lower part of the figure. An electrically insulating material that becomes polarized in an electric field is called a dielectric .","[Figure 18.5] shows that the negative charge in the molecules in the material shifts to the left, toward the positive charge of the capacitor. This shift is due to the electric field, which applies a force to the left on the electrons in the molecules of the dielectric. The right sides of the molecules are now missing a bit of negative charge, so their net charge is positive.","All electrically insulating materials are dielectrics, but some are better dielectrics than others. A good dielectric is one whose molecules allow their electrons to shift strongly in an electric field. In other words, an electric field pulls their electrons a fair bit away from their atom, but they do not escape completely from their atom (which is why they are insulators).","[Figure 18.5] shows a macroscopic view of a dielectric in a charged capacitor. Notice that the electric-field lines in the capacitor with the dielectric are spaced farther apart than the electric-field lines in the capacitor with no dielectric. This means that the electric field in the dielectric is weaker, so it stores less electrical potential energy than the electric field in the capacitor with no dielectric.","Where has this energy gone? In fact, the molecules in the dielectric act like tiny springs, and the energy in the electric field goes into stretching these springs. With the electric field thus weakened, the voltage difference between the two sides of the capacitor is smaller, so it becomes easier to put more charge on the capacitor. Placing a dielectric in a capacitor before charging it therefore allows more charge and potential energy to be stored in the capacitor. A parallel plate with a dielectric has a capacitance of","where \\(κ\\) ( kappa ) is a dimensionless constant called the dielectric constant . Because \\(κ\\) is greater than 1 for dielectrics, the capacitance increases when a dielectric is placed between the capacitor plates. The dielectric constant of several materials is shown in [Table_18_01]."],"figures":[{"sourceId":"fs-id1167064599965","filename":"CNX_HSPhysics_18_05_dielectric.jpg","relativePath":"media/CNX_HSPhysics_18_05_dielectric.jpg","alt":"This figure has two panels. The upper panel shows two parallel strips in vertical orientation. The strip on the left has a series of “plus” signs and is labeled “plus Q”. The strip on the right has a series of “minus” signs and is labeled “minus Q”. Between the strips is a series of horizontal arrows pointing from left to right, and below the arrows is a label that says “No dielectric”. The lower panel shows two similar strips, with the strip on the left containing “plus” signs and labeled “plus Q”, and the one on the right containing “minus” signs and labeled “minus Q”. Between the strips is a grid of elliptical shapes of equal size, each containing a “minus” sign on the left and a “plus” sign on the right. The whole group of ellipses is labeled “With dielectric”, and one ellipse is labeled “Polarized molecule”. A label pointing to a minus sign within an ellipse says “Negative charge on surface”, and another label pointing to a plus sign within an ellipse says “Positive charge on surface”. Also, a series of short, rightward pointing arrows lie on each side of the grid of ellipses."},{"sourceId":"fs-id1167064799164","filename":"CNX_HSPhysics_18_05_dielectinc.jpg","relativePath":"media/CNX_HSPhysics_18_05_dielectinc.jpg","alt":"This figure has two panels. The upper panel shows two parallel strips in vertical orientation. The strip on the left has a series of plus signs and is labeled “plus Q”. The strip on the right has a series of minus signs and is labeled “minus Q”. Between the strips is a series of horizontal arrows pointing from left to right, and below the arrows is a label that says “No dielectric”. The lower panel shows two similar strips, with the strip on the left containing plus signs and labeled “plus Q”, and the one on the right containing minus signs and labeled “minus Q”. Between the strips is a rectangle labeled “With dielectric”, with a few minus signs along its left edge and a few plus signs along its right edge. Also, between the strips are several long arrows pointing rightward and going from the left strip to the right one. In addition, a series of short, rightward pointing arrows lie between the left strip and the rectangle and between the rectangle and the right strip."}],"tables":[{"sourceId":"Table_18_01","headers":["Material","Dielectric Constant ( \\(κ\\) )"],"rows":[["Vacuum","1.00000"],["Air","1.00059"],["Fused quartz","3.78"],["Neoprene rubber","6.7"],["Nylon","3.4"],["Paper","3.7"],["Polystyrene","2.56"],["Pyrex glass","5.6"],["Silicon oil","2.5"],["Strontium titanate","233"],["Teflon","2.1"],["Water","80"]]}]},{"uid":"hsphys.ch18.sec05.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["Newton’s law of universal gravitation is","where \\(G = 6.67\\, \\times \\,{10}^{- 11}{\\text{m}}^{3}\\text{/kg} \\cdot {\\text{s}}^{2}\\) . This describes the gravitational force between two point masses m 1 and m 2 .","Coulomb’s law is","where \\(k = 8.99\\, \\times \\,{10}^{9}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/C}}^{\\text{2}}\\) . This describes the electric force between two point charges q 1 and q 2 .","(a) Describe how the force in each case depends on the distance r between the objects. How do the forces change if the distance is reduced by half? If the distance is doubled?","(b) Describe the similarities and differences between the two laws. Consider the signs of the quantities that create the interaction (i.e., mass and charge), the constants G and k , and their dependence on separation r .","(c) Given that the electric force is much stronger than the gravitational force, discuss why the law for gravitational force was discovered much earlier than the law for electric force.","(d) Consider a hydrogen atom, which is a single proton orbited by a single electron. The electric force holds the electron and proton together so that the hydrogen atom has a radius of about \\(0.5\\, \\times \\,{10}^{-10}\\text{m}\\) . Assuming the force between electron and proton does not change, what would be the approximate radius of the hydrogen atom if \\(k = 6.67\\, \\times \\,{10}^{-11}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/C}}^{\\text{2}}\\) ?"],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch18.sec05.ex01","number":"18.5.1","title":"Capacitance and Charge Stored in a Parallel Plate Capacitor","problem":"(a) What is the capacitance of a parallel-plate capacitor with metal plates, each of area 1.00 m 2 , separated by 0.0010 m? (b) What charge is stored in this capacitor if a voltage of 3.00 × 10 3 V is applied to it?\nStrategy FOR (A)\nUse the equation \\({C}_{0} = {ε}_{0}\\frac{A}{d}\\) .","problemImages":[],"strategy":null,"solution":"Solution for (a)\nEntering the given values into this equation for the capacitance of a parallel-plate capacitor yields\n\\(C = {ε}_{0}\\frac{A}{d} = (8.85\\, \\times \\,{10}^{-12}\\text{F/m})\\frac{1.00{\\text{m}}^{\\text{2}}}{0.0010\\,\\text{m}} = 8.9\\, \\times \\,{10}^{-9}\\text{F} = \\text{8}\\text{.9}\\text{nF}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"This small value for the capacitance indicates how difficult it is to make a device with a large capacitance. Special techniques help, such as using very-large-area thin foils placed close together or using a dielectric (to be discussed below)."},{"uid":"hsphys.ch18.sec05.ex02","number":"18.5.2","title":"What battery is needed to charge a capacitor?","problem":"Your friend provides you with a \\(10\\mu \\text{F}\\) capacitor. To store \\(120\\mu \\text{C}\\) on this capacitor, what voltage battery should you buy?","problemImages":[],"strategy":"Use the equation \\(C = Q/V\\) to find the voltage needed to charge the capacitor.","solution":"Solving \\(C = Q/V\\) for the voltage gives \\(V = Q/C\\) . Inserting \\(C = 10\\mu \\text{F} = 10\\, \\times \\,{10}^{-6}\\text{F}\\) and \\(Q = 120\\mu \\text{C} = 120\\, \\times \\,{10}^{-6}\\text{C}\\) gives\n\\(V = \\frac{Q}{C} = \\frac{120\\, \\times \\,{10}^{-6}\\text{C}}{10\\, \\times \\,{10}^{-6}\\text{F}} = 12\\,\\text{V}\\)","solutionImages":[],"solutionTables":[],"discussion":"Such a battery should be easy to procure. There is still a question of whether the battery contains enough energy to provide the desired charge. The equation \\({U}_{E} = \\frac{1}{2}C{V}^{2}\\) allows us to calculate the required energy.\n\\({U}_{E} = \\frac{1}{2}C{V}^{2} = \\frac{1}{2}(10\\, \\times \\,{10}^{- 6}\\text{F}){(12\\,\\text{V})}^{2} = 72\\,\\text{mJ}\\) A typical commercial battery can easily provide this much energy."},{"uid":"hsphys.ch18.sec05.ex03","number":"18.5.3","title":"Capacitor for Camera Flash","problem":"A typical flash for a point-and-shoot camera uses a capacitor of about \\(200\\,\\mu \\text{F}\\) . (a) If the potential difference between the capacitor plates is 100 V—that is, 100 V is placed “across the capacitor,” how much energy is stored in the capacitor? (b) If the dielectric used in the capacitor were a 0.010-mm-thick sheet of nylon, what would be the surface area of the capacitor plates?\nStrategy FOR (A)\nGiven that \\(V = 100\\,\\text{V}\\) and \\(C = 200\\, \\times \\,{10}^{-6}\\text{F}\\), we can use the equation \\({U}_{E} = \\frac{1}{2}C{V}^{2}\\), to find the electric potential energy stored in the capacitor.","problemImages":[],"strategy":null,"solution":"Solution for (a)\nInserting the given quantities into \\({U}_{E} = \\frac{1}{2}C{V}^{2}\\) gives\n\\({U}_{E} = \\frac{1}{2}C{V}^{2} = \\frac{1}{2}(200\\, \\times \\,{10}^{- 6}\\text{F}){(100\\,\\text{V})}^{2} = 1.0\\,\\text{J}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"This is enough energy to lift a 1-kg ball about 1 m up from the ground. The flash lasts for about 0.001 s, so the power delivered by the capacitor during this brief time is \\(P = \\frac{{U}_{E}}{t} = \\frac{1.0\\,\\text{J}}{0.001\\,\\text{s}} = 1\\,\\text{kW}\\) . Considering that a car engine delivers about 100 kW of power, this is not bad for a little capacitor!"}],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":["The capacitance of a capacitor depends only on the geometry of the capacitor and the materials from which it is made. It does not depend on the voltage across the capacitor.","Capacitors store electrical energy in the electric field between their plates.","A dielectric material is an insulator that is polarized in an electric field.","Putting a dielectric between the plates of a capacitor increases the capacitance of the capacitor."],"glossary":[{"term":"capacitor","termVi":"Tụ điện (C = Q/V)","definition":"arrangement of objects that can store electrical energy by virtue of their geometry","definitionVi":"Linh kiện gồm hai bản dẫn đặt song song ngăn cách bởi lớp điện môi, dùng để tích và phóng năng lượng điện trường (đơn vị điện dung: Farad, F).","memoryTipVi":"Năng lượng tụ điện: U = ½ C·V²."},{"term":"dielectric","termVi":"Chất điện môi (trong tụ điện)","definition":"electrically insulating material that becomes polarized in an electric field","definitionVi":"Lớp vật liệu cách điện chèn giữa hai bản tụ điện giúp TĂNG điện dung C của tụ lên κ lần.","memoryTipVi":"Vừa tăng điện dung C vừa ngăn hai bản tụ chạm nhau phóng điện."}],"assessments":[{"uid":"hsphys.ch18.sec05.q003","sourceId":"fs-id1167065788616","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the voltage on a 35 μF with 25 nC of charge?","images":[],"choices":[{"label":"a","text":"8.75 × 10 -13 V"},{"label":"b","text":"0.71 × 10 -3 V"},{"label":"c","text":"1.4 × 10 -3 V"},{"label":"d","text":"1.4 × 10 3 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q004","sourceId":"fs-id1167065000353","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Which voltage is across a 100 μF capacitor that stores 10 J of energy?","images":[],"choices":[{"label":"a","text":"-4.5 × 10 2 V"},{"label":"b","text":"4.5 × 10 2 V"},{"label":"c","text":"±4.5 × 10 2 V"},{"label":"d","text":"±9 × 10 2 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q005","sourceId":"fs-id1167065953887","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"With 12 V across a capacitor, it accepts 10 mC of charge. What is its capacitance?","images":[],"choices":[{"label":"a","text":"0.83 μ F"},{"label":"b","text":"83 μ F"},{"label":"c","text":"120 μ F"},{"label":"d","text":"830 μ F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q006","sourceId":"fs-id1167066137104","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A parallel-plate capacitor has an area of 10 cm 2 and the plates are separated by 100 μ m . If the capacitor contains paper between the plates, what is its capacitance?","images":[],"choices":[{"label":"a","text":"3.3 × 10 -10 F"},{"label":"b","text":"3.3 × 10 -8 F"},{"label":"c","text":"3.3 × 10 -6 F"},{"label":"d","text":"3.3 × 10 -4 F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q007","sourceId":"fs-id1167065898269","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"You insert a dielectric into an air-filled capacitor. How does this affect the energy stored in the capacitor?","images":[],"choices":[{"label":"a","text":"Energy stored in the capacitor will remain same."},{"label":"b","text":"Energy stored in the capacitor will decrease."},{"label":"c","text":"Energy stored in the capacitor will increase."},{"label":"d","text":"Energy stored in the capacitor will increase first, and then it will decrease."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q008","sourceId":"eip-id1166849845850","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or false Placing a dielectric between the plates of a capacitor increases the energy of the capacitor.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q009","sourceId":"eip-id1166849832315","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or false The electric field in an air-filled capacitor is reduced when a dielectric is inserted between the plates.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q010","sourceId":"fs-id1167066030967","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"When you insert a dielectric into a capacitor that has been charged and then disconnected from the charging battery, the energy stored in the capacitor decreases. If you take the dielectric out, the energy increases again. Where does this energy go in the former case, and where does the energy come from in the latter case?","images":[],"choices":[{"label":"a","text":"Energy is released by the dielectric when it is introduced between the plates and then reabsorbed when it is removed."},{"label":"b","text":"The energy goes into polarizing the dielectric when it is added. When you remove the dielectric, energy comes from your work pulling on the dielectric."},{"label":"c","text":"Energy goes into you when you insert the dielectric, and comes from you when you remove it."},{"label":"d","text":"Energy is released to polarize the dielectric when it is introduced between the plates. The polarized dielectric transfers the energy back into the capacitor when the dielectric is removed."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q011","sourceId":"fs-id1167065788616","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the voltage on a 35 μF with 25 nC of charge?","images":[],"choices":[{"label":"a","text":"8.75 × 10 -13 V"},{"label":"b","text":"0.71 × 10 -3 V"},{"label":"c","text":"1.4 × 10 -3 V"},{"label":"d","text":"1.4 × 10 3 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q012","sourceId":"fs-id1167065000353","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Which voltage is across a 100 μF capacitor that stores 10 J of energy?","images":[],"choices":[{"label":"a","text":"-4.5 × 10 2 V"},{"label":"b","text":"4.5 × 10 2 V"},{"label":"c","text":"±4.5 × 10 2 V"},{"label":"d","text":"±9 × 10 2 V"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q013","sourceId":"fs-id1167065953887","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"With 12 V across a capacitor, it accepts 10 mC of charge. What is its capacitance?","images":[],"choices":[{"label":"a","text":"0.83 μ F"},{"label":"b","text":"83 μ F"},{"label":"c","text":"120 μ F"},{"label":"d","text":"830 μ F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q014","sourceId":"fs-id1167066137104","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A parallel-plate capacitor has an area of 10 cm 2 and the plates are separated by 100 μ m . If the capacitor contains paper between the plates, what is its capacitance?","images":[],"choices":[{"label":"a","text":"3.3 × 10 -10 F"},{"label":"b","text":"3.3 × 10 -8 F"},{"label":"c","text":"3.3 × 10 -6 F"},{"label":"d","text":"3.3 × 10 -4 F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q015","sourceId":"fs-id1167062368324","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A 4.12 µ F parallel-plate capacitor has a plate area of 200 cm 2 and a plate separation of 10 µ m . What dielectric is between the plates?","images":[],"choices":[{"label":"a","text":"233, the dielectric is strontium titanate"},{"label":"b","text":"466, the dielectric is strontium"},{"label":"c","text":"699, the dielectric is strontium nitrate"},{"label":"d","text":"1,000, the dielectric is strontium chloride"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q017","sourceId":"fs-id1167065030321","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which magnitude of charge is stored on each plate of a 12 µF capacitor with 12 V applied across it?","images":[],"choices":[{"label":"a","text":"1.0 × 10 6 C"},{"label":"b","text":"1.0 × 10 6 C"},{"label":"c","text":"1.4 × 10 4 C"},{"label":"d","text":"1.4 × 10 4 C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q018","sourceId":"fs-id1167065968410","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the capacitance of a parallel-plate capacitor with an area of 200 cm 2 , a distance of 0.20 mm between the plates, and polystyrene as a dielectric?","images":[],"choices":[{"label":"a","text":"2.3 nC"},{"label":"b","text":"0.89 nC"},{"label":"c","text":"23 nC"},{"label":"d","text":"8.9 nC"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q019","sourceId":"eip-id1166847411231","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which factors determine the capacitance of a device?","images":[],"choices":[{"label":"a","text":"Capacitance depends only on the materials that make up the device."},{"label":"b","text":"Capacitance depends on the electric field surrounding the device."},{"label":"c","text":"Capacitance depends on the geometric and material parameters of the device."},{"label":"d","text":"Capacitance depends only on the mass of the capacitor"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q021","sourceId":"fs-id1167064616824","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A capacitor with neoprene rubber as the dielectric stores 0.185 mJ of energy with a voltage of 50 V across the plates. If the area of the plates is 500 cm 2 , what is the plate separation?","images":[],"choices":[{"label":"a","text":"20 µm"},{"label":"b","text":"20 m"},{"label":"c","text":"80 µm"},{"label":"d","text":"80 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q022","sourceId":"fs-id1167065763077","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Explain why a storm cloud before a lightning strike is like a giant capacitor.","images":[],"choices":[{"label":"a","text":"The storm cloud acts as a giant charged capacitor, as it can store a large amount of charge."},{"label":"b","text":"The storm cloud acts as a giant charged capacitor, as it contains a high amount of excess charges."},{"label":"c","text":"The storm cloud acts as a giant charged capacitor, as it splits in two capacitor plates with equal and opposite charge."},{"label":"d","text":"The storm cloud acts as a giant charged capacitor, as it splits in two capacitor plates with unequal and opposite charges."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q023","sourceId":"fs-id1167066025777","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A storm cloud is 2 km above the surface of Earth. The lower surface of the cloud is approximately 2 km 2 in area. What is the approximate capacitance of this storm cloud-Earth system?","images":[],"choices":[{"label":"a","text":"9 × 10 15 F"},{"label":"b","text":"9 × 10 -9 F"},{"label":"c","text":"17.7 × 10 -15 F"},{"label":"d","text":"17.7 × 10 -9 F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q024","sourceId":"fs-id1167064641346","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A 12 μF air-filled capacitor has 12 V across it. If the surface charge on each capacitor plate is σ = 7.2 mC / m 2 , what is the attractive force of one capacitor plate toward the other?","images":[],"choices":[{"label":"a","text":"0.81 × 10 5 N"},{"label":"b","text":"0.81 × 10 6 N"},{"label":"c","text":"1.2 × 10 5 N"},{"label":"d","text":"1.2 × 10 6 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch18.sec05.q025","sourceId":"fs-id1167064927754","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Explain why capacitance should be inversely proportional to the separation between the plates of a capacitor.","images":[],"choices":[{"label":"a","text":"Capacitance is directly proportional to the electric field, which is inversely proportional to the distance between the capacitor plates."},{"label":"b","text":"Capacitance is inversely proportional to the electric field, which is inversely proportional to the distance between the capacitor plates."},{"label":"c","text":"Capacitance is inversely proportional to the electric field, which is directly proportional to the distance between the capacitor plates."},{"label":"d","text":"Capacitance is directly proportional to the electric field, which is directly proportional to the distance between the capacitor plates."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":3,"subsectionCount":3,"workedExampleCount":3,"snapLabCount":0,"glossaryCount":2,"assessmentCount":21}}],"summary":{"totalSections":6,"totalKeyEquations":11,"totalWorkedExamples":11,"totalSnapLabs":3,"totalGlossaryTerms":15,"totalAssessments":110,"referencedMediaCount":24},"qualityGate":{"passed":true,"checkedUids":139,"errors":[],"warnings":[]}};
